    const ev = try signedKind(arena, signer, kp, 1_800_000_000, 30023, &.{}, "# raw markdown");
    const note = main.noteFrom(ev, 1_800_000_000);
    try testing.expectEqual(@as(u16, 0), note.content_len);
}

test "a kind nothing can draw keeps its content out of the body" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    const kp = try signer.keyPairFromSecretKey([_]u8{0x34} ** 32);

    // A file metadata event: its content is empty by design, and what it holds
    // is in its tags.
    const ev = try signedKind(arena, signer, kp, 1_800_000_000, 1063, &.{}, "not a sentence");
    const note = main.noteFrom(ev, 1_800_000_000);
    try testing.expectEqual(main.KindRender.unsupported, main.kindRender(note.kind));
    try testing.expectEqual(@as(u16, 0), note.content_len);
}

test "a real kind:0 is unsupported, and the default does not hide it" {
    // `Note.kind` defaults to 1 so a fixture or a scratch struct reads as a text
    // note. This is the case that default could have masked: an event whose kind
    // really is 0 must still be refused, because `noteFrom` writes the real kind
    // over the default rather than leaving it.
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    const kp = try signer.keyPairFromSecretKey([_]u8{0x35} ** 32);

    const ev = try signedKind(arena, signer, kp, 1_800_000_000, 0, &.{}, "{\"name\":\"somebody\"}");
    const note = main.noteFrom(ev, 1_800_000_000);
    try testing.expectEqual(@as(u16, 0), note.kind);
    try testing.expectEqual(main.KindRender.unsupported, main.kindRender(note.kind));

    // And a Note nobody filled from an event is still a text note.
    const blank = main.Note{};
    try testing.expectEqual(main.KindRender.note, main.kindRender(blank.kind));
}

test "every surface answers the same way about one kind" {
    // The point of having a single dispatch: a quote card, a thread and
    // open_event cannot disagree about the same event.
    try testing.expectEqual(main.KindRender.note, main.kindRender(1));
    try testing.expectEqual(main.KindRender.note, main.kindRender(main.comment_kind));
    try testing.expectEqual(main.KindRender.article, main.kindRender(30023));
    try testing.expectEqual(main.KindRender.media, main.kindRender(20));
    try testing.expectEqual(main.KindRender.media, main.kindRender(21));
    try testing.expectEqual(main.KindRender.media, main.kindRender(22));
    try testing.expectEqual(main.KindRender.unsupported, main.kindRender(1063));
    try testing.expectEqual(main.KindRender.unsupported, main.kindRender(31923));
}

/// A NIP-18 repost of `target`, tagged the way this app writes them.
fn signedRepost(
    arena: std.mem.Allocator,
    signer: nostr.keys.Signer,
    kp: nostr.keys.KeyPair,
    created_at: i64,
    target: nostr.event.Event,
    content: []const u8,
) !nostr.event.Event {
    const id_hex = try std.fmt.allocPrint(arena, "{x}", .{target.id});
    const author_hex = try std.fmt.allocPrint(arena, "{x}", .{target.pubkey});
    // Allocated, not `&[_][]const u8{...}` inline in an array literal: those are
    // temporaries, and the `Tag` slices pointing at them dangle by the time the
    // store encodes the event. It shows up as a nonsense tag length inside
    // `encodeEvent` rather than as anything that names this line.
    const e_tag = try arena.dupe([]const u8, &.{ "e", id_hex, "", author_hex });
    const p_tag = try arena.dupe([]const u8, &.{ "p", author_hex });
    const tags = try arena.alloc(nostr.event.Tag, 2);
    tags[0] = e_tag;
    tags[1] = p_tag;
    return nostr.event.create(arena, signer, kp, created_at, main.repost_kind, tags, content, null);
}

test "a repost points at the last e tag" {
    const a = [_]u8{0xaa} ** 32;
    const b = [_]u8{0xbb} ** 32;
    var buf_a: [64]u8 = undefined;
    var buf_b: [64]u8 = undefined;
    _ = try std.fmt.bufPrint(&buf_a, "{x}", .{a});
    _ = try std.fmt.bufPrint(&buf_b, "{x}", .{b});

    // The LAST one, which is what Amethyst reads. A repost normally carries one,
    // so the two answers differ only for a malformed event, and differing from
    // the network about a malformed event shows a row nobody else does.
    const tags = [_]nostr.event.Tag{
        &[_][]const u8{ "e", &buf_a },
        &[_][]const u8{ "p", &buf_a },
        &[_][]const u8{ "e", &buf_b },
    };
    try testing.expectEqualSlices(u8, &b, &(main.repostTargetId(&tags).?));

    // Nothing to point at is not a row.
    const none = [_]nostr.event.Tag{&[_][]const u8{ "p", &buf_a }};
    try testing.expect(main.repostTargetId(&none) == null);
}

test "a repost by a follow shows the note it points at, named" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    const me = try signer.keyPairFromSecretKey([_]u8{0x61} ** 32);
    const author = try signer.keyPairFromSecretKey([_]u8{0x62} ** 32);
    main.setIdentityForTest([_]u8{0x61} ** 32);
    defer main.clearIdentityForTest();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var pbuf: [128]u8 = undefined;
    const db_path = try std.fmt.bufPrintZ(&pbuf, ".zig-cache/tmp/{s}/repost.mdb", .{tmp.sub_path});
    var store = try nostr.store.Store.open(db_path, .{});
    defer store.deinit();

    const note = try signedNote(arena, signer, author, 1_800_000_000, "the original words");
    _ = try store.ingest(arena, note, .{});
    const boost = try signedRepost(arena, signer, me, 1_800_000_100, note, "");
    _ = try store.ingest(arena, boost, .{});

    var model = main.initialModel();
    model.stage = .ready;
    main.reconcileForTest(&model, &store, 1_800_000_200);

    // One row, and it is the REPOSTED note: its id, its author, its words. That
    // is what makes the counts under it belong to the note rather than to the
    // wrapper, because engagement is already keyed on `event_id`.
    try testing.expectEqual(@as(usize, 1), model.notes_len);
    const row = model.notes[0];
    try testing.expectEqualSlices(u8, &note.id, &row.event_id);
    try testing.expectEqualSlices(u8, &author.public_key, &row.pubkey);
    try testing.expectEqualStrings("the original words", row.content());
    try testing.expect(row.has_reposter);
    try testing.expectEqualSlices(u8, &me.public_key, &row.reposter);
}

test "a note already in the feed is not drawn again by a repost of it" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    const me = try signer.keyPairFromSecretKey([_]u8{0x63} ** 32);
    main.setIdentityForTest([_]u8{0x63} ** 32);
    defer main.clearIdentityForTest();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var pbuf: [128]u8 = undefined;
    const db_path = try std.fmt.bufPrintZ(&pbuf, ".zig-cache/tmp/{s}/dedup.mdb", .{tmp.sub_path});
    var store = try nostr.store.Store.open(db_path, .{});
    defer store.deinit();

    // My own note, and my own repost of it: the note is in the window under its
    // own name already.
    const note = try signedNote(arena, signer, me, 1_800_000_000, "said once");
    _ = try store.ingest(arena, note, .{});
    const boost = try signedRepost(arena, signer, me, 1_800_000_100, note, "");
    _ = try store.ingest(arena, boost, .{});

    var model = main.initialModel();
    model.stage = .ready;
    main.reconcileForTest(&model, &store, 1_800_000_200);

    try testing.expectEqual(@as(usize, 1), model.notes_len);
    try testing.expectEqualStrings("said once", model.notes[0].content());
}

test "a repost whose note nobody has draws no row" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    const me = try signer.keyPairFromSecretKey([_]u8{0x64} ** 32);
    const author = try signer.keyPairFromSecretKey([_]u8{0x65} ** 32);
    main.setIdentityForTest([_]u8{0x64} ** 32);
    defer main.clearIdentityForTest();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var pbuf: [128]u8 = undefined;
    const db_path = try std.fmt.bufPrintZ(&pbuf, ".zig-cache/tmp/{s}/missing.mdb", .{tmp.sub_path});
    var store = try nostr.store.Store.open(db_path, .{});
    defer store.deinit();

    // The wrapper is stored, the note it points at is not. A row drawn from the
    // wrapper alone would be the reposter's name over an empty body, which is
    // the thing being avoided. Notedeck drops the row for the same reason.
    const note = try signedNote(arena, signer, author, 1_800_000_000, "never stored");
    const boost = try signedRepost(arena, signer, me, 1_800_000_100, note, "");
    _ = try store.ingest(arena, boost, .{});

    var model = main.initialModel();
    model.stage = .ready;
    main.reconcileForTest(&model, &store, 1_800_000_200);
    try testing.expectEqual(@as(usize, 0), model.notes_len);
}

test "first run shows the onboarding welcome, not the feed" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    // Default stage is onboarding (a fresh install with no identity on disk).
    var model = main.initialModel();
    const tree = try buildTree(arena, &model);

    try testing.expect(findAnyText(tree.root, "Welcome to Nostr") != null);
    try testing.expect(findAnyText(tree.root, "Create your identity") != null);
    // The sign-in paths (import a key or connect a signer) share one field with a
    // Continue action.
    try testing.expect(findAnyText(tree.root, "Continue") != null);
    // The feed's connecting header does not show on the welcome screen.
    try testing.expect(findAnyText(tree.root, "Connecting…") == null);
}

test "login text is classified by prefix" {
    try testing.expectEqual(main.LoginTarget.nsec, main.classifyLogin("nsec1abcdef"));
    try testing.expectEqual(main.LoginTarget.bunker, main.classifyLogin("bunker://pubkey?relay=wss://r"));
    try testing.expectEqual(main.LoginTarget.nsec, main.classifyLogin("  nsec1withspace  "));
    // An npub (read-only) is not a sign-in path yet, nor is arbitrary text.
    try testing.expectEqual(main.LoginTarget.invalid, main.classifyLogin("npub1abcdef"));
    try testing.expectEqual(main.LoginTarget.invalid, main.classifyLogin("hello"));
    try testing.expectEqual(main.LoginTarget.invalid, main.classifyLogin(""));
}

test "the settings screen shows the identity, the way to the signer, and logout" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    // Signed in, because half this screen is about the identity: a guest has no
    // profile to edit and no key to back up.
    main.setIdentityForTest([_]u8{9} ** 32);
    defer main.clearIdentityForTest();
    var model = main.initialModel();
    model.stage = .settings;
    const tree = try buildTree(arena, &model);

    try testing.expect(findAnyText(tree.root, "Settings") != null);
    // Every section the design names, in the order it names them.
    try testing.expect(findAnyText(tree.root, "IDENTITY") != null);
    try testing.expect(findAnyText(tree.root, "RELAYS") != null);
    try testing.expect(findAnyText(tree.root, "APPEARANCE") != null);
    try testing.expect(findAnyText(tree.root, "FEED") != null);
    // The identity card says what signs, and offers the way into the profile.
    try testing.expect(findAnyText(tree.root, "Signing via Notary") != null);
    try testing.expect(findAnyText(tree.root, "Edit profile") != null);
    try testing.expect(findAnyText(tree.root, "Copy npub") != null);
    // The key is NOT offered here, and that is the point. Backing it up happens
    // in the signer's own window, which is the process that holds it: Plaza
    // showing a key would be Plaza holding one. What this screen owes the
    // reader is the way to that window.
    try testing.expect(findAnyText(tree.root, "Reveal secret key") == null);
    // The way to that window is the "Open Notary" link on the signer row, which
    // needs both a keyholder holding the key and the window binary beside the
    // app. Neither is true of a bare test model, so its presence is not asserted
    // here; its absence from THIS screen is the property that matters.
    // So is the media proxy, which is a privacy setting with no other UI.
    try testing.expect(findAnyText(tree.root, "Media proxy") != null);
    try testing.expect(findAnyText(tree.root, "Load media previews") != null);
    // The logout entry point is present; the confirmation is not yet.
    try testing.expect(findAnyText(tree.root, "Log out") != null);
    try testing.expect(findAnyText(tree.root, "Cancel") == null);
    // The version line renders.
    // The version app.zon declares, not a literal. This line used to say
    // "Plaza 0.1.0" and passed happily while the shipped app was 0.2.2, because
    // both the screen and the test were reading the same stale copy.
    const shown = try std.fmt.allocPrint(arena, "Plaza {s}", .{main.plaza_version_for_test});
    try testing.expect(findAnyText(tree.root, shown) != null);
    try testing.expect(main.plaza_version_for_test.len > 0);
}

test "a guest is not offered a profile to edit" {
    // A guest has no key: nothing to read their profile from and nothing that
    // could sign an edit. Offering the sheet would sit on "Reading your current
    // profile" for the rest of the session.
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    main.clearIdentityForTest();
    var model = main.initialModel();
    model.stage = .settings;
    const tree = try buildTree(arena, &model);
    try testing.expect(findAnyText(tree.root, "IDENTITY") != null);
    try testing.expect(findAnyText(tree.root, "Edit profile") == null);

    // And reaching for it anyway routes to the join sheet rather than opening a
    // sheet that can never finish.
    var fx: main.EffectsForTest = undefined;
    main.update(&model, .open_profile_edit, &fx);
    try testing.expect(!model.editing_profile);
    try testing.expect(model.joining);
}

test "a kind:0 profile gives an author a display name" {
    main.resetProfilesForTest();
    defer main.resetProfilesForTest();

    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    const kp = try signer.keyPairFromSecretKey([_]u8{7} ** 32);

    // Before a profile is known, the author renders as an abbreviated npub.
    const ev = try signedNote(arena, signer, kp, 1_800_000_000, "hi");
    const before = main.noteFrom(ev, 1_800_000_000);
    try testing.expect(std.mem.startsWith(u8, before.author(), "npub1"));

    // Seed the cache from kind:0 metadata; the author now renders as the name,
    // and no avatar is loaded yet (initials fallback).
    const p = main.upsertProfile(kp.public_key).?;
    main.parseMetadataInto(p, "{\"display_name\":\"Satoshi\",\"name\":\"nakamoto\",\"picture\":\"https://ex.com/a.png\"}");
    const after = main.noteFrom(ev, 1_800_000_000);
    try testing.expectEqualStrings("Satoshi", after.author());
    try testing.expectEqual(@as(u64, 0), after.avatar_id());
}

test "malformed or empty kind:0 leaves the npub fallback" {
    main.resetProfilesForTest();
    defer main.resetProfilesForTest();

    const pk = [_]u8{8} ** 32;
    const p = main.upsertProfile(pk).?;
    // Not JSON, and JSON with no usable fields: neither sets a name.
    main.parseMetadataInto(p, "this is not json");
    main.parseMetadataInto(p, "{\"about\":\"just a bio\"}");

    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    const kp = try signer.keyPairFromSecretKey(pk);
    const ev = try signedNote(arena_state.allocator(), signer, kp, 1_800_000_000, "x");
    const note = main.noteFrom(ev, 1_800_000_000);
    try testing.expect(std.mem.startsWith(u8, note.author(), "npub1"));
}

test "nostr: mentions render as @name or a short npub" {
    main.resetProfilesForTest();
    defer main.resetProfilesForTest();

    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const pk = [_]u8{5} ** 32;
    const npub = try nostr.nip19.encodeNpub(arena, pk);

    var buf: [220]u8 = undefined;

    // Unknown pubkey: the mention becomes a short @npub, and "nostr:" is gone.
    const src_unknown = try std.fmt.allocPrint(arena, "hey nostr:{s} welcome", .{npub});
    const n1 = main.renderContent(&buf, src_unknown, "");
    const out1 = buf[0..n1];
    try testing.expect(std.mem.indexOf(u8, out1, "nostr:") == null);
    try testing.expect(std.mem.indexOf(u8, out1, "@npub1") != null);
    try testing.expect(std.mem.startsWith(u8, out1, "hey @npub1"));

    // Known pubkey: the mention becomes @<name>.
    const p = main.upsertProfile(pk).?;
    main.parseMetadataInto(p, "{\"name\":\"jack\"}");
    const n2 = main.renderContent(&buf, src_unknown, "");
    const out2 = buf[0..n2];
    try testing.expect(std.mem.indexOf(u8, out2, "@jack") != null);
    try testing.expect(std.mem.indexOf(u8, out2, "nostr:") == null);
}

