    var result = try store.query(arena, .{ .authors = &authors, .kinds = &kinds, .limit = 1 });
    defer result.deinit();
    var count: usize = 0;
    var saw_bob = false;
    for (result.events[0].tags) |tag| {
        if (tag.len >= 2 and std.mem.eql(u8, tag[0], "p")) {
            count += 1;
