    try testing.expectEqual(@as(usize, 2), count);
    try testing.expect(!saw_bob);
}

test "a place brings its own relays, and a feed can be about people" {
    // The document is fiatjaf's Monero Hallway instance, trimmed. Its "People"
    // feed names twenty pubkeys and NO relay, and Plaza used to drop any feed
    // without one: the room simply never appeared, with nothing said about why.
    const doc =
        \\{"appName": "Monero Hallway",
        \\ "readRepliesFrom": ["wss://xmr.usenostr.org", "wss://nostr.xmr.rocks"],
        \\ "publishTargets": ["wss://xmr.usenostr.org", "wss://nostr.xmr.rocks"],
        \\ "hardcodedFeeds": [
        \\   {"name": "Monero Topic", "relays": ["wss://topic.relays.land/monero"]},
        \\   {"name": "People", "pubkeys": [
        \\     "35d38fa2efb7c9f4b1bf20a4d2cded731b152ed871a0aac9d72347265c9b42d8",
        \\     "5f17d7be02ab98c11360c241556017377fa0f00127cd0a912f128e288c8c4dca",
        \\     "0c45d7d45edb0fadda4215d36ca0d9aba0c771b85d3717764b8a128d5e443e4d"]}]}
    ;
    const place = main.parsePlace(testing.allocator, doc) orelse return error.PlaceRefused;

    // Both feeds, not one.
    try testing.expectEqual(@as(u8, 2), place.feeds_len);
    try testing.expectEqualStrings("Monero Topic", place.feeds[0].name());
    try testing.expectEqualStrings("People", place.feeds[1].name());

    // The relay feed keeps its relay and names nobody.
    try testing.expectEqualStrings("wss://topic.relays.land/monero", place.feeds[0].relay());
    try testing.expectEqual(@as(usize, 0), place.feeds[0].people().len);

    // The people feed names its people and no relay, so it has to ask the
    // place's own.
    try testing.expectEqual(@as(usize, 3), place.feeds[1].people().len);
    try testing.expectEqual(@as(usize, 0), place.feeds[1].relay().len);

    try testing.expectEqual(@as(u8, 2), place.read_relays_len);
    try testing.expectEqualStrings("wss://xmr.usenostr.org", place.readRelay(0));
    try testing.expectEqual(@as(u8, 2), place.write_relays_len);
    try testing.expectEqualStrings("wss://xmr.usenostr.org", place.writeRelay(0));

    // Absent means additive, never "only mine". A place that says nothing must
    // not be read as taking the reader's own relays away.
    try testing.expect(!place.read_exclusive);
    try testing.expect(!place.write_exclusive);
}

test "a place says where it reads a kind, and a pattern is checked before it is offered" {
    // fiatjaf's Monero instance names Nosmero for kind 1. The pattern needs a
    // QUERY, which is exactly what `isSafeShareUrl` refuses, so handlers get
    // their own gate rather than a loosened version of that one.
    const doc =
        \\{"appName": "Monero Hallway",
        \\ "clientHandlers": {"byKind": {"1": [{"name": "Nosmero", "urlPattern": "https://nosmero.com/?thread={e}"}]}, "fallback": null},
        \\ "hardcodedFeeds": [{"name": "x", "relays": ["wss://ok.example"]}]}
    ;
    const place = main.parsePlace(testing.allocator, doc) orelse return error.PlaceRefused;
    const h = place.handlerFor(1) orelse return error.NoHandler;
    try testing.expectEqualStrings("Nosmero", h.name());
    try testing.expectEqualStrings("https://nosmero.com/?thread={e}", h.pattern());
    // And nothing is claimed for a kind the place said nothing about.
    try testing.expect(place.handlerFor(30023) == null);
}

test "a short welcome does not reserve a tall empty card" {
    // The card used to reserve a fixed 380 points whatever the host wrote, so a
    // two-line welcome sat above three hundred points of nothing with the Close
    // button stranded at the bottom of an empty box.
    const short = "## Welcome!\n\nTwo lines, that is all.";
    const tall = main.placeHomeHeightForTest(short);
    try testing.expect(tall > 0);
    try testing.expect(tall < 140);

    // And a long one is still capped, so a host cannot push the buttons off the
    // screen with an essay.
    var long_buf: [2000]u8 = undefined;
    @memset(&long_buf, 'x');
    try testing.expectEqual(@as(f32, 380), main.placeHomeHeightForTest(&long_buf));
}

test "measuring a markdown line counts what is drawn, not what is written" {
    // This is what made the first estimate useless. One paragraph of the Monero
    // welcome carries a link whose address is two hundred characters that are
    // never drawn, so the line measured four times longer than it reads.
    const link = "See [the client](/nevent1qvzqqqqqqypzqwlsccluhy6xxsr6l9a9uhhxf75g85g8a709tprjcn4e42h053va) here";
    try testing.expectEqual(@as(usize, "See the client here".len), main.visibleLenForTest(link));

    // Heading markers are syntax, not text.
    try testing.expectEqual(@as(usize, "Welcome!".len), main.visibleLenForTest("## Welcome!"));
    // Plain text is itself.
    try testing.expectEqual(@as(usize, 5), main.visibleLenForTest("hello"));
}

test "walking into a room with no logo does not leave the last room's mark behind" {
    // Reported: entered Monero Hallway, then opened the BASSPISTOL link, and
    // Monero's logo was sitting on BASSPISTOL's Info card.
    //
    // The identity check sat BELOW the "this place ships no logo" early return,
    // so a room with nothing of its own never reached the line that drops the
    // last room's mark. Walking OUT to your own feed cleared it, which is why
    // only room-to-room could show it.
    var fx = main.inertEffectsForTest();
    var model = main.initialModel();
    main.resetPlacesForTest();
    defer main.resetPlacesForTest();
    defer main.setPlaceLogoIdForTest(0);

    // A slot nothing else in this process holds: these tests share the pool.
    var slot: u64 = 0;
    var i: u64 = 1;
    while (i <= 16) : (i += 1) {
        if (std.mem.eql(u8, main.imageIdOwnerNameForTest(i), "free")) {
            slot = i;
            break;
        }
    }
    if (slot == 0) return error.NoFreeSlot;

    // Standing in a room whose mark is loaded and on screen.
    main.setPlaceLogoLoadedForTest(slot, [_]u8{0xa1} ** 32, "moneroh");
    try testing.expect(main.placeLogoShownForTest());

    // Straight into a different room, one that ships no logo at all.
    main.visitPlaceForTest([_]u8{0xa2} ** 32, "outernational-dancehall", "BASSPISTOL");
    main.scanPlaceLogoForTest(&fx, &model);
    try testing.expect(!main.placeLogoShownForTest());

    // And one host running two rooms: the host alone is not a place, so the
    // second room does not inherit the first one's mark either.
    main.setPlaceLogoLoadedForTest(slot, [_]u8{0xa3} ** 32, "room-one");
    try testing.expect(main.placeLogoShownForTest());
    main.visitPlaceForTest([_]u8{0xa3} ** 32, "room-two", "Second Room");
    main.scanPlaceLogoForTest(&fx, &model);
    try testing.expect(!main.placeLogoShownForTest());
}

test "the place's logo is not a slot the pool can hand to a face" {
    // Reported: the logo appeared, then turned into somebody's avatar as the
    // feed loaded behind it. Image ids come from a shared pool, and a slot this
    // app holds but the pool does not KNOW about reads as free, so the next face
    // to arrive was handed the id the Info card was drawing.
    // A slot nothing else in this process holds: these tests share the pool.
    var slot: u64 = 0;
    var i: u64 = 1;
    while (i <= 16) : (i += 1) {
        if (std.mem.eql(u8, main.imageIdOwnerNameForTest(i), "free")) {
            slot = i;
            break;
        }
    }
    if (slot == 0) return error.NoFreeSlot;

    main.setPlaceLogoIdForTest(slot);
    defer main.setPlaceLogoIdForTest(0);

    // The pool has to name it. "free" here is the whole bug: a slot this app
    // holds and the pool calls free is one it will hand to the next face.
    try testing.expectEqualStrings("place_logo", main.imageIdOwnerNameForTest(slot));

    // On screen this pass: untouchable, like a banner or a face being looked at.
    main.markPlaceLogoSeenForTest();
    try testing.expect(main.placeLogoUntouchableForTest());

    // A later pass with the place gone: the slot goes back rather than being
    // held forever.
    main.agePlaceLogoForTest();
    try testing.expect(!main.placeLogoUntouchableForTest());
}

test "saving a place keeps everything the parser understood" {
    // The places file is what a restart reads, so a field the parser
    // understands and the writer forgets is a field that works once and is gone
    // by morning. That is exactly what happened: the logo, the community's
    // relays, its handlers, its own words for a room and a feed's people were
    // all read correctly and then dropped on the next save.
    const doc =
        \\{"appName":"Monero Hallway",
        \\ "logoUrl":"https://example.test/logo.png",
        \\ "readRepliesFrom":["wss://a.example"],
        \\ "publishTargets":["wss://b.example"],
        \\ "clientHandlers":{"byKind":{"1":[{"name":"Nosmero","urlPattern":"https://nosmero.com/?thread={e}"}]}},
        \\ "translations":{"Empty list.":"Private, and proud of it.","Loading":"Mixing…","Lost in the void":"Unlinkable."},
        \\ "hardcodedFeeds":[{"name":"People","pubkeys":["35d38fa2efb7c9f4b1bf20a4d2cded731b152ed871a0aac9d72347265c9b42d8"]}]}
    ;
    const first = main.parsePlace(testing.allocator, doc) orelse return error.PlaceRefused;

    var out: std.ArrayList(u8) = .empty;
    defer out.deinit(testing.allocator);
    try main.writePlaceDocumentForTest(testing.allocator, &out, &first);

    // Read back what was written: the round trip is the property, not the bytes.
    const again = main.parsePlace(testing.allocator, out.items) orelse return error.RoundTripRefused;
    try testing.expectEqualStrings("https://example.test/logo.png", again.logo());
    try testing.expectEqual(@as(u8, 1), again.read_relays_len);
    try testing.expectEqualStrings("wss://a.example", again.readRelay(0));
    try testing.expectEqual(@as(u8, 1), again.write_relays_len);
    try testing.expectEqualStrings("wss://b.example", again.writeRelay(0));
    const h = again.handlerFor(1) orelse return error.NoHandler;
    try testing.expectEqualStrings("Nosmero", h.name());
    try testing.expectEqualStrings("Mixing…", again.loadingLine());
    try testing.expectEqualStrings("Private, and proud of it.", again.emptyLine());
    // And the feed is still about people.
    try testing.expectEqual(@as(u8, 1), again.feeds_len);
    try testing.expectEqual(@as(usize, 1), again.feeds[0].people().len);
}

test "an image with no alt text leaves nothing behind" {
    // The renderer draws an image as its ALT text, which is right for a client
    // that spends its image budget on faces. `![](url)` has no alt, so the
    // renderer does not take it as an image at all and the reader gets a
    // literal `![]` and the raw URL as a link. Seen in fiatjaf's Monero
    // welcome, which is written exactly that way.
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();

    const src =
        "Welcome!\n\n![](https://example.test/sticker.png)\n\nRead on.";
    const out = main.stripEmptyImagesForTest(arena_state.allocator(), src);
    try testing.expect(std.mem.indexOf(u8, out, "![]") == null);
    try testing.expect(std.mem.indexOf(u8, out, "https://example.test") == null);
    // And the host's actual words are untouched.
    try testing.expect(std.mem.indexOf(u8, out, "Welcome!") != null);
    try testing.expect(std.mem.indexOf(u8, out, "Read on.") != null);

    // An image that DOES name itself is left alone: the renderer draws that alt
    // text, which is the whole point of the format.
    const kept = "see ![a sticker](https://example.test/s.png) here";
    try testing.expectEqualStrings(kept, main.stripEmptyImagesForTest(arena_state.allocator(), kept));

    // And syntax that is not an image is not touched either.
    const unclosed = "![](broken";
    try testing.expectEqualStrings(unclosed, main.stripEmptyImagesForTest(arena_state.allocator(), unclosed));
}

test "a place may name what its own room says, and nothing else" {
    // Hallway's `translations` maps its OWN English to replacements, and
    // Plaza's wording is different, so nothing matches by accident. Three keys
    // are picked for what they mean in a room. Everything else in the map is
    // read and ignored on purpose: a place may name its room, not rename
    // Settings.
    const doc =
        \\{"appName": "Monero Hallway",
        \\ "translations": {
        \\   "Empty list.": "Empty list. Private, and proud of it.",
        \\   "Loading": "Mixing…",
        \\   "Lost in the void": "Lost in the void, unlinkable and untraceable",
        \\   "Not following anyone": "Fungible, and free."},
        \\ "hardcodedFeeds": [{"name": "x", "relays": ["wss://ok.example"]}]}
    ;
    const place = main.parsePlace(testing.allocator, doc) orelse return error.PlaceRefused;
    try testing.expectEqualStrings("Empty list. Private, and proud of it.", place.emptyLine());
    try testing.expectEqualStrings("Mixing…", place.loadingLine());
    try testing.expectEqualStrings("Lost in the void, unlinkable and untraceable", place.lostLine());

    // A place that rewrites nothing leaves the app's own words alone, which is
    // what an absent key has to mean or every silent place would blank its room.
    const plain =
        \\{"appName": "Plain", "hardcodedFeeds": [{"name": "x", "relays": ["wss://ok.example"]}]}
    ;
    const p2 = main.parsePlace(testing.allocator, plain) orelse return error.PlaceRefused;
    try testing.expectEqual(@as(usize, 0), p2.emptyLine().len);
    try testing.expectEqual(@as(usize, 0), p2.loadingLine().len);
}

test "a handler pattern this app will not open" {
    // Each of these is a way of sending the reader somewhere other than where
    // the row says. The row names the host, so the host is the thing that must
    // not be up for grabs.
    try testing.expect(main.isSafeHandlerUrl("https://nosmero.com/?thread={e}"));
    try testing.expect(main.isSafeHandlerUrl("https://n.example/e/{e}"));

    // Not https.
    try testing.expect(!main.isSafeHandlerUrl("http://nosmero.com/?thread={e}"));
    // Credentials in the authority: the row would name the wrong host.
    try testing.expect(!main.isSafeHandlerUrl("https://evil.example@real.example/{e}"));
    // A placeholder in the HOST, which would let a note id choose the server.
    try testing.expect(!main.isSafeHandlerUrl("https://{e}.example/x"));
    // No placeholder is a fixed link that ignores which note was pressed.
    try testing.expect(!main.isSafeHandlerUrl("https://nosmero.com/"));
    // Several is an ambiguity not worth resolving.
    try testing.expect(!main.isSafeHandlerUrl("https://n.example/{e}/{e}"));
    // A backslash, and a control character.
    try testing.expect(!main.isSafeHandlerUrl("https://n.example\\@x/{e}"));
    try testing.expect(!main.isSafeHandlerUrl("https://n.example/\x01{e}"));
}

test "a place cannot point the reader at something that is not a relay" {
    // Every address a stranger fills in goes through the same gate. A place
    // naming http, or a credential, or nothing at all, keeps none of it.
    const doc =
        \\{"appName": "Nowhere",
        \\ "readRepliesFrom": ["http://insecure.example", "wss://ok.example"],
        \\ "publishTargets": ["not a url"],
        \\ "publishTargetsExclusive": true,
        \\ "hardcodedFeeds": [{"name": "x", "relays": ["wss://ok.example"]}]}
    ;
    const place = main.parsePlace(testing.allocator, doc) orelse return error.PlaceRefused;

    try testing.expectEqual(@as(u8, 1), place.read_relays_len);
    try testing.expectEqualStrings("wss://ok.example", place.readRelay(0));

    // And exclusivity over an empty list is refused. A place claiming "only
    // mine" while naming none would otherwise silence the reader completely.
    try testing.expectEqual(@as(u8, 0), place.write_relays_len);
    try testing.expect(!place.write_exclusive);
}

test "a note waits before it is signed, and pressing again takes it back" {
    // plaza#330. The pause is on the NEAR side of the signature on purpose:
    // once a note is signed and out, a kind:5 is a request a relay may ignore
    // and everyone already holding the event keeps it. An undo that ran after
    // publishing would be a button that cannot do what it says.
    // Off unless asked for. Turning it on for everybody would make a note that
    // suddenly does not post read as a fault before it reads as a safeguard.
    try testing.expectEqual(@as(i64, 0), main.postDelayForTest());

    // Nothing held, nothing due.
    try testing.expect(!main.postIsDue(0, 1_800_000_000));

    // Held, and not due until the clock runs out.
    const due: i64 = 1_800_000_005;
    try testing.expect(!main.postIsDue(due, 1_800_000_000));
    try testing.expect(!main.postIsDue(due, 1_800_000_004));
    try testing.expect(main.postIsDue(due, due));
    try testing.expect(main.postIsDue(due, due + 60));

    // What the button counts down. Never zero while something is held: a button
    // reading "Undo 0" has already gone.
    try testing.expectEqual(@as(i64, 5), main.postSecondsLeft(due, 1_800_000_000));
    try testing.expectEqual(@as(i64, 1), main.postSecondsLeft(due, 1_800_000_004));
    try testing.expectEqual(@as(i64, 1), main.postSecondsLeft(due, due + 10));
    try testing.expectEqual(@as(i64, 0), main.postSecondsLeft(0, 1_800_000_000));
}

test "the ways out of the composer all take a held note back" {
    // Both found by asking what happens on the paths that are not the happy
    // one. Pressing Post and then Cancel used to publish, seconds later, the
    // note whose composer had just been dismissed.
    main.setIdentityForTest([_]u8{0x7a} ** 32);
    defer main.clearIdentityForTest();

    var model = main.initialModel();
    var fx: main.EffectsForTest = undefined;

    main.holdPostForTest(1_800_000_000);
    try testing.expect(main.postHeldForTest());
    main.update(&model, .close_compose, &fx);
    try testing.expect(!main.postHeldForTest());

    // A reply is exactly as final as a note, and it belongs to the thread being
    // left. Leaving it armed would publish it into a conversation the reader
    // had walked away from.
    main.holdReplyForTest(1_800_000_000);
    try testing.expect(main.replyHeldForTest());
    main.update(&model, .close_thread, &fx);
    try testing.expect(!main.replyHeldForTest());
}

test "an unfollow the keyholder never signed is put back" {
    // Plaza v0.13.0 shipped unable to sign anything: Notary refused every local
    // request until somebody answered a question no window could reach. The app
    // took the refusal, moved the follow set anyway, and showed the press as
    // done. The acceptance journey caught it by reading the list back off the
    // relay and finding the unfollow had reached nothing.
    //
    // The signing half is fixed in Notary. This is the other half: the app must
    // not go on claiming a write that no signature ever covered.
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    const kp = try signer.keyPairFromSecretKey([_]u8{93} ** 32);
    main.setIdentityForTest([_]u8{93} ** 32);
    defer main.clearIdentityForTest();
    main.forgetFollowsForTest();
    main.setSignerKindHelperForTest();
    defer main.setSignerKindLocalForTest();
    main.silenceTestSignerForTest(true);
    defer main.silenceTestSignerForTest(false);

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var pbuf: [128]u8 = undefined;
    const db_path = try std.fmt.bufPrintZ(&pbuf, ".zig-cache/tmp/{s}/undo.mdb", .{tmp.sub_path});
    var store = try nostr.store.Store.open(db_path, .{});
    defer store.deinit();
    main.setStoreForTest(&store);
    defer main.setStoreForTest(null);

    const tags = [_]nostr.event.Tag{
        &.{ "p", "aa" ** 32 },
        &.{ "p", "bb" ** 32 },
        &.{ "p", "cc" ** 32 },
    };
    const existing = try nostr.event.create(arena, signer, kp, 1_800_000_000, 3, &tags, "", null);
    _ = try main.plazaIngestVerifiedForTest(arena, existing, signer);
    main.noteOwnContactsAnsweredForTest(kp.public_key);

    var bob: [32]u8 = undefined;
    @memset(&bob, 0xbb);
    var fx: main.EffectsForTest = undefined;
    try testing.expect(main.writeFollowForTest(&fx, bob, false));

    // The press moves the live list first, which is deliberate: the feed has to
    // answer immediately. Nothing here disputes that.
    try testing.expectEqual(@as(usize, 2), main.followSetForTest().len);

    // And the keyholder refuses. 403 is the concrete one this shipped against:
    // "awaiting approval", for a question nobody could reach.
    main.handleHelperSignedForTest(.{ .key = 0, .outcome = .ok, .status = 403, .body = "" });

    var model = main.initialModel();
    main.scanHelperSignForTest(&model);

    // Put back, all three, with the one that was taken out among them.
    const live = main.followSetForTest();
    try testing.expectEqual(@as(usize, 3), live.len);
    var saw_bob = false;
    for (live) |f| {
        if (std.mem.eql(u8, &f, &bob)) saw_bob = true;
    }
    try testing.expect(saw_bob);

    // And the reader is told. A silent revert is the same lie told backwards.
    try testing.expect(model.toast_text().len > 0);
}

test "no follow is written before a relay has said who you already follow" {
    // The hard rule. "Nobody answered" and "you follow nobody" look identical
    // from here, and publishing under the second reading replaces a list of
    // hundreds with a handful of accounts this app chose.
    main.setIdentityForTest([_]u8{93} ** 32);
    defer main.clearIdentityForTest();
    main.forgetFollowsForTest();
    main.forgetOwnRecordAnswersForTest();

    main.resetRelaysForTest();
    main.setIdentityMintedForTest(false);
    try testing.expect(!main.canWriteFollows());
    var someone: [32]u8 = undefined;
    @memset(&someone, 0xab);
    var fx: main.EffectsForTest = undefined;
    try testing.expect(!main.writeFollowForTest(&fx, someone, true));

    // Relay silence is NOT evidence for an imported key. Every relay in the pool
    // answering changes nothing, because on a cold import the pool is this app's
    // bootstrap five, chosen before the reader's own kind:10002 was read: five
    // clean answers happily coexist with eight hundred follows on relays this
    // app has never dialed.
    const me = main.activePubkeyForTest().?;
    for (0..5) |i| main.noteContactsAnsweredByForTest(i, me);
    try testing.expect(!main.canWriteFollows());
    try testing.expect(!main.writeFollowForTest(&fx, someone, true));
    // Nor does it put the question: the reader's own relays have not been named,
    // so "every relay finished" is not true of the relays that matter.
    try testing.expect(!main.needsFreshConsentForTest(.follows));
    try testing.expect(main.followBlockedReason() != null);

    // A key MINTED here is different in kind: it provably has no history, so
    // there is nothing a write could destroy.
    main.setIdentityMintedForTest(true);
    try testing.expect(main.canWriteFollows());
    try testing.expect(main.followBlockedReason() == null);

    // And that fact belongs to the key, not the session.
    main.setIdentityForTest([_]u8{94} ** 32);
    main.setIdentityMintedForTest(false);
    try testing.expect(!main.canWriteFollows());
}

test "a contact list read from a relay becomes the feed, and an empty one does not" {
    const tags = [_]nostr.event.Tag{
        &.{ "p", "11" ** 32 },
        &.{ "p", "22" ** 32 },
        // A duplicate and a malformed entry: neither should reach the feed.
        &.{ "p", "11" ** 32 },
        &.{ "p", "not-hex" },
        &.{"p"},
    };
    var out: [128][32]u8 = undefined;
    const n = main.followsFromTagsForTest(&tags, &out);
    try testing.expectEqual(@as(usize, 2), n);

    // A list with no usable p tag is not a list: adopting it would empty the
    // reader's feed on the word of one malformed event.
    const empty_tags = [_]nostr.event.Tag{&.{ "p", "nope" }};
    try testing.expectEqual(@as(usize, 0), main.followsFromTagsForTest(&empty_tags, &out));
}

test "one reader's follows are never another's" {
    main.forgetFollowsForTest();
    main.setIdentityForTest([_]u8{95} ** 32);
    defer main.clearIdentityForTest();
    var list: [2][32]u8 = undefined;
    @memset(&list[0], 0x11);
    @memset(&list[1], 0x22);
    try testing.expect(main.setFollowsForTest(&list, 1_800_000_000));
    try testing.expectEqual(@as(usize, 2), main.followSetForTest().len);

    // A different account, the same table: back to the pack until their own
    // list arrives. Showing them a stranger's follows would be showing them
    // somebody else's reading.
    main.setIdentityForTest([_]u8{96} ** 32);
    try testing.expectEqual(@as(usize, 9), main.followSetForTest().len);
}

test "a follow changes the generation, so the live subscriptions re-ask" {
    // Without this a follow shows nothing new until the socket happens to drop,
    // which reads as a broken button.
    main.forgetFollowsForTest();
    main.setIdentityForTest([_]u8{97} ** 32);
    defer main.clearIdentityForTest();
    const before = main.followGeneration();
    var list: [1][32]u8 = undefined;
    @memset(&list[0], 0x33);
    try testing.expect(main.setFollowsForTest(&list, 1_800_000_000));
    try testing.expect(main.followGeneration() != before);

    // The same list again is not a change, and must not churn every relay.
    const after = main.followGeneration();
    try testing.expect(!main.setFollowsForTest(&list, 1_800_000_000));
    try testing.expectEqual(after, main.followGeneration());
}

test "the feed's scope line stops calling your own follows hand-picked" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    main.forgetFollowsForTest();
    var guest = main.initialModel();
    try testing.expectEqualStrings("Starter pack", guest.scope_name());
    try testing.expect(std.mem.indexOf(u8, guest.scope_voices(arena), "hand-picked") != null);

    main.setIdentityForTest([_]u8{98} ** 32);
    defer main.clearIdentityForTest();
    var list: [3][32]u8 = undefined;
    for (&list, 0..) |*e, i| @memset(e, @intCast(i + 1));
    _ = main.setFollowsForTest(&list, 1_800_000_000);

    var mine = main.initialModel();
    try testing.expectEqualStrings("Following", mine.scope_name());
    const voices = mine.scope_voices(arena);
    try testing.expect(std.mem.indexOf(u8, voices, "hand-picked") == null);
    try testing.expect(std.mem.indexOf(u8, voices, "3 accounts") != null);
}

test "a full follow list rebuilds the feed fast enough to do it every second" {
    // The store opens ONE LMDB cursor per author and then, for every event it
    // emits, linearly picks the newest across all live streams. Its own comment
    // says "stream counts are small". That is true at nine and the reason this
    // test exists: the feed rebuilds whenever the store's event count moves,
    // which the live pool makes about once a second, so a linear-per-event pick
    // over a full follow list is a frame hitch the reader feels rather than a
    // number in a benchmark.
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    main.setIdentityForTest([_]u8{99} ** 32);
    defer main.clearIdentityForTest();
    main.forgetFollowsForTest();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var pbuf: [128]u8 = undefined;
    const db_path = try std.fmt.bufPrintZ(&pbuf, ".zig-cache/tmp/{s}/perf.mdb", .{tmp.sub_path});
    var store = try nostr.store.Store.open(db_path, .{});
    defer store.deinit();

    // A full list, each with a handful of notes, which is the shape a real
    // reader's feed has.
    const follows = 128;
    var list: [follows][32]u8 = undefined;
    var i: usize = 0;
    while (i < follows) : (i += 1) {
        var secret: [32]u8 = undefined;
        @memset(&secret, @intCast((i % 200) + 1));
        secret[31] = @intCast(i & 0xff);
        secret[30] = @intCast((i >> 8) & 0xff);
        const kp = signer.keyPairFromSecretKey(secret) catch continue;
        list[i] = kp.public_key;
        var n: usize = 0;
        while (n < 4) : (n += 1) {
            const body = try std.fmt.allocPrint(arena, "note {d} from {d}", .{ n, i });
            const ev = try nostr.event.create(arena, signer, kp, 1_800_000_000 + @as(i64, @intCast(i * 10 + n)), 1, &.{}, body, null);
            _ = try store.ingest(arena, ev, .{});
        }
    }
    _ = main.setFollowsForTest(&list, 1_800_000_000);
    try testing.expectEqual(@as(usize, follows), main.followSetForTest().len);

    var model = main.initialModel();
    model.stage = .ready;
    // One rebuild to warm the page cache, then time a run of them.
    main.reconcileForTest(&model, &store, 1_800_002_000);
    try testing.expect(model.notes_len > 0);

    // `std.time.Timer` is gone in 0.16; the awake clock is what the app itself
    // times relay round trips with.
    var threaded = std.Io.Threaded.init(testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const started = std.Io.Timestamp.now(io, .awake);
    const rounds = 10;
    var r: usize = 0;
    while (r < rounds) : (r += 1) {
        main.invalidateFeedForTest();
        main.reconcileForTest(&model, &store, 1_800_002_000);
    }
    const elapsed = started.durationTo(std.Io.Timestamp.now(io, .awake));
    const per_rebuild_ns = @as(u64, @intCast(@max(elapsed.toNanoseconds(), 0))) / rounds;

    // The budget is one frame at 60Hz, which is the honest bar: this runs on
    // the UI thread on a timer, so anything slower is a visible stutter every
    // second rather than a slow benchmark. Generous enough not to be flaky on a
    // loaded CI box, tight enough to catch the cliff.
    const budget_ns = 16 * std.time.ns_per_ms;
    std.debug.print("\n[perf] {d} follows: {d}us per feed rebuild (budget {d}us)\n", .{ follows, per_rebuild_ns / 1000, budget_ns / 1000 });
    if (per_rebuild_ns > budget_ns) {
        std.debug.print(
            "\nfeed rebuild with {d} follows took {d}us, budget {d}us\n",
            .{ follows, per_rebuild_ns / 1000, budget_ns / 1000 },
        );
        return error.FeedRebuildTooSlow;
    }
}

test "a note's follow entry says which way it goes, and refuses when it cannot know" {
    // The one control that writes a contact list. Every state it can be in is
    // asserted here, because the harness cannot open a thread by pressing a row
    // (true on main too), and because the dangerous state is the one that must
    // NOT offer a press: a Follow that fires before the app has been told who
    // the reader already follows replaces that list with this app's guesses.
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const author = [_]u8{0x55} ** 32;
    var model = main.initialModel();
    model.stage = .ready;
    model.viewing_thread = 1;
    model.thread_root = threadNote(0xAA, 100, 0);
    model.thread_root.id = 1;
    model.thread_root.pubkey = author;

    // A guest: the menu offers Follow, and pressing it raises the join sheet
    // rather than failing quietly.
    main.clearIdentityForTest();
    main.forgetFollowsForTest();
    main.forgetOwnRecordAnswersForTest();
    {
        const p = try painted.Painted.render(arena, &model);
        const menu = noteContext(p) orelse return error.NoContextMenu;
        try testing.expect(menu.label("Follow") != null);
    }

    // Signed in, but nobody has said who they follow yet: the entry says what it
    // is waiting for, and refuses the press.
    main.setIdentityForTest([_]u8{0x66} ** 32);
    main.setIdentityMintedForTest(false);
    defer main.clearIdentityForTest();
    {
        const p = try painted.Painted.render(arena, &model);
        const menu = noteContext(p) orelse return error.NoContextMenu;
        const waiting = menu.label("Looking for your follow list…") orelse return error.NotWaiting;
        try testing.expect(!waiting.enabled);
        try testing.expect(menu.label("Unfollow") == null);
    }

    // A key minted here has no history to lose: Follow.
    main.resetRelaysForTest();
    main.setIdentityMintedForTest(true);
    {
        const p = try painted.Painted.render(arena, &model);
        const menu = noteContext(p) orelse return error.NoContextMenu;
        try testing.expect(menu.label("Follow") != null);
        try testing.expect(menu.label("Looking for your follow list…") == null);
    }

    // Already following: the way back out is offered.
    var list: [1][32]u8 = undefined;
    list[0] = author;
    _ = main.setFollowsForTest(&list, 1_800_000_000);
    {
        const p = try painted.Painted.render(arena, &model);
        const menu = noteContext(p) orelse return error.NoContextMenu;
        try testing.expect(menu.label("Unfollow") != null);
    }

    // Their own note: no follow control at all, in either direction.
    model.thread_root.pubkey = main.activePubkeyForTest().?;
    {
        const p = try painted.Painted.render(arena, &model);
        const menu = noteContext(p) orelse return error.NoContextMenu;
        const mine = menu.label("This is you") orelse return error.NotSelf;
        try testing.expect(!mine.enabled);
        try testing.expect(menu.label("Unfollow") == null);
    }
}

