// ------------------------------------------------------- NIP-89 the client tag

test "a note says nothing about what wrote it unless the reader asks" {
    // OFF by default, which is the choice Sepehr made and NIP-89 hints at: the
    // tag is a small permanent fact about the reader attached to everything they
    // write, and it follows the note to every relay forever.
    const gpa = testing.allocator;
    main.setClientTag(false);
    defer main.setClientTag(false);

    const base = [_]nostr.event.Tag{&.{ "e", "ab" ** 32 }};
    {
        const out = main.withClientTag(gpa, 1, &base);
        try testing.expectEqual(@as(usize, 1), out.len);
    }

    main.setClientTag(true);
    // A note, and a repost of one: the things the reader actually wrote.
    for ([_]u16{ 1, 6 }) |kind| {
        const out = main.withClientTag(gpa, kind, &base);
        defer {
            gpa.free(out[out.len - 1]);
            gpa.free(out);
        }
        try testing.expectEqual(@as(usize, 2), out.len);
        try testing.expectEqualStrings("client", out[1][0]);
        try testing.expectEqualStrings("Plaza", out[1][1]);
    }
    // Machinery is not writing. A reaction and a deletion carry nothing: they
    // would broadcast the same fact more widely for nothing the reader can see,
    // which is the opposite of what an opt-in privacy switch is for.
    for ([_]u16{ 7, 5, 3, 0 }) |kind| {
        const out = main.withClientTag(gpa, kind, &base);
        try testing.expectEqual(@as(usize, 1), out.len);
    }
}

test "what a stranger's note claims about its client is treated as foreign text" {
    const cases = [_]struct { value: []const u8, shown: ?[]const u8 }{
        .{ .value = "Plaza", .shown = "Plaza" },
        .{ .value = "  Amethyst  ", .shown = "Amethyst" },
        // Too long for the row is CUT, not thrown away: the name is still
        // evidence about the note, and refusing it outright discarded the whole
        // fact. Fourteen characters.
        .{ .value = "x" ** 40, .shown = "x" ** 14 },
        // And cut by CHARACTER, not by byte. A byte cap is about eight
        // characters of Japanese and twenty-four of English, so it refused a
        // legitimate name in one script and accepted a far wider one in another.
        .{ .value = "クライアントの名前がとても長い", .shown = "クライアントの名前がとても長" },
        // A newline in a meta row is how a row stops looking like a row.
        .{ .value = "Damus\nHACKED", .shown = null },
        .{ .value = "", .shown = null },
        .{ .value = "   ", .shown = null },
    };
    for (cases) |c| {
        const ev = nostr.event.Event{
            .id = [_]u8{0} ** 32,
            .pubkey = [_]u8{0} ** 32,
            .created_at = 1_800_000_000,
            .kind = 1,
            .tags = &.{&.{ "client", c.value }},
            .content = "hi",
            .sig = [_]u8{0} ** 64,
        };
        if (c.shown) |want| {
            try testing.expectEqualStrings(want, main.clientOf(ev) orelse return error.NothingShown);
        } else {
            try testing.expect(main.clientOf(ev) == null);
        }
    }
    // A note with no tag at all draws nothing, never "via unknown": what a note
    // does not say is not a fact about it.
    const bare = nostr.event.Event{
        .id = [_]u8{0} ** 32,
        .pubkey = [_]u8{0} ** 32,
        .created_at = 1_800_000_000,
        .kind = 1,
        .tags = &.{},
        .content = "hi",
        .sig = [_]u8{0} ** 64,
    };
    try testing.expect(main.clientOf(bare) == null);
}

test "the feed draws via without spending a node on it" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var model = main.initialModel();
    model.stage = .ready;
    const plain = nostr.event.Event{
        .id = [_]u8{0xC1} ** 32,
        .pubkey = [_]u8{0x51} ** 32,
        .created_at = 1_800_000_000,
        .kind = 1,
        .tags = &.{},
        .content = "no client tag here",
        .sig = [_]u8{0} ** 64,
    };
    var tagged = plain;
    tagged.id = [_]u8{0xC2} ** 32;
    tagged.tags = &.{&.{ "client", "Amethyst" }};
    tagged.content = "written elsewhere";

    model.notes[0] = main.noteFrom(plain, 1_800_000_000);
    model.notes[1] = main.noteFrom(tagged, 1_800_000_000);
    model.notes_len = 2;

    const before = try buildTree(arena, &model);
    const nodes_with = countNodes(before.root);
    try testing.expect(findAnyTextContaining(before.root, "via Amethyst"));
    // The note that says nothing gets no "via" of its own.
    try testing.expect(!findAnyTextContaining(before.root, "via Plaza"));

    // And the row costs the same either way: the name rides as a second SPAN of
    // the paragraph the time already occupies, not as a node beside it. A feed
    // row is priced against a per-view ceiling that refuses the whole screen.
    model.notes[1] = main.noteFrom(plain, 1_800_000_000);
    model.notes[1].id = 999;
    const after = try buildTree(arena, &model);
    try testing.expectEqual(nodes_with, countNodes(after.root));
}

test "the time and via line is one line, whatever the note says it was written with" {
    // "11h via Damus Notedeck" used to wrap. The second line hung into the
    // handle's row, and because a row's height and the width this box is
    // measured at are settled in different passes, scrolling flickered it
    // between two lines and one, sometimes losing the second line entirely.
    //
    // Asserted as the FLAG rather than as a measured height, and that is an
    // admitted limit rather than a shortcut: this harness lays out the real tree
    // but does not carry the real glyph metrics (see the header of painted.zig),
    // so a height assertion here answers a question about a font that is not the
    // one the window uses. It passed with the wrap put back, which is how that
    // was found out. The flag is the whole of the decision, so the flag is what
    // is guarded here; the pixels were checked by rendering the app.
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var model = main.initialModel();
    model.stage = .ready;
    const ev = nostr.event.Event{
        .id = [_]u8{0xD1} ** 32,
        .pubkey = [_]u8{0x52} ** 32,
        .created_at = 1_800_000_000,
        .kind = 1,
        .tags = &.{&.{ "client", "Damus Notedeck" }},
        .content = "wrapped once",
        .sig = [_]u8{0} ** 64,
    };
    model.notes[0] = main.noteFrom(ev, 1_800_003_600);
    model.notes_len = 1;

    const p = try painted.Painted.render(arena, &model);
    var found = false;
    for (p.layout.nodes) |node| {
        const w = node.widget;
        if (w.kind != .text or w.spans.len < 2) continue;
        if (std.mem.indexOf(u8, w.text, " via ") == null) continue;
        found = true;
        if (!w.text_no_wrap) {
            std.debug.print("the meta line \"{s}\" is allowed to wrap again\n", .{w.text});
            return error.MetaLineCanWrap;
        }
    }
    try testing.expect(found);
}

test "the time and via line ends where the card ends" {
    // It stopped ending there. `wrap = false` fixed a flicker and silently
    // broke the alignment beside it: the toolkit gives a NON-WRAPPING paragraph
    // an infinite max_width (text_spans.zig:627), and its aligner returns early
    // on a width that is not finite (:565), so `text_alignment = .end` is
    // ignored on any single-line paragraph. The box stayed in the right place
    // and the words inside it sat at the left, so "35m via Amethyst" hung a
    // ragged gap off the card's edge that grew as the string got shorter.
    //
    // So the alignment is done by LAYOUT now, which the toolkit does honour: a
    // stated-width row, a spacer that takes the slack, and a paragraph that
    // hugs its own text at the end of it.
    //
    // Asserted against the note body, because both live in the same column and
    // the whole complaint was that one ended short of the other. Box geometry,
    // not glyph metrics, so this harness can answer it (see painted.zig).
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    // Short, long, and longer than the column: the gap the reader saw was
    // widest for the shortest string, and the longest is what the column was
    // measured against in the first place.
    for ([_][]const u8{ "Amethyst", "Damus Notedeck", "An Absurdly Long Client Name" }) |client| {
        var model = main.initialModel();
        model.stage = .ready;
        const ev = nostr.event.Event{
            .id = [_]u8{0xD2} ** 32,
            .pubkey = [_]u8{0x53} ** 32,
            .created_at = 1_800_000_000,
            .kind = 1,
            .tags = &.{&.{ "client", client }},
            .content = "GM",
            .sig = [_]u8{0} ** 64,
        };
        model.notes[0] = main.noteFrom(ev, 1_800_002_100);
        model.notes_len = 1;

        const p = try painted.Painted.render(arena, &model);
        var meta_right: ?f32 = null;
        var body_right: ?f32 = null;
        for (p.layout.nodes) |node| {
            const w = node.widget;
            if (w.kind != .text) continue;
            const f = w.frame;
            if (std.mem.indexOf(u8, w.text, " via ") != null) meta_right = f.x + f.width;
            if (std.mem.eql(u8, w.text, "GM")) body_right = f.x + f.width;
        }
        const meta = meta_right orelse return error.NoMetaLine;
        const body = body_right orelse return error.NoBody;
        if (@abs(meta - body) > 0.5) {
            std.debug.print(
                "\"{s}\": the meta line ends at {d:.1}, the card ends at {d:.1}\n",
                .{ client, meta, body },
            );
            return error.MetaLineNotFlush;
        }
    }
}

test "the feed asks about the notes it is SHOWING, not only the ones that arrived" {
    // The watch list was built purely from events coming down the wire, and the
    // feed's own REQ carries a `since` off the newest stored note. So on any
    // launch but the first, the feed draws notes nobody has asked a relay about
    // and every one of them reads zero replies, zero reposts, zero likes and
    // zero sats for the session. A guest saw it worst: a starter-pack feed is
    // nearly all store once it has been read once, which made it look like
    // guests do not get counts at all.
    var notes: [3]main.Note = undefined;
    for (&notes, 0..) |*n, i| {
        n.* = main.Note{ .created_at = 1_800_000_000 };
        n.id = @intCast(100 + i);
        n.event_id = [_]u8{@intCast(0xA0 + i)} ** 32;
    }
    main.publishFeedWatchForTest(notes[0..]);

    // A socket that has heard nothing still has the whole visible feed to ask
    // about. This is the case that used to watch nothing at all.
    var ids: [main.engagementWatchCapForTest]i64 = undefined;
    var hex: [main.engagementWatchCapForTest][64]u8 = undefined;
    try testing.expectEqual(@as(usize, 3), main.mergeFeedWatchForTest(&ids, &hex, 0));
    try testing.expectEqual(@as(i64, 100), ids[0]);
    try testing.expectEqualStrings("a0" ** 32, &hex[0]);

    // What the socket already knew is kept, and nothing is asked about twice.
    ids[0] = 100;
    hex[0] = [_]u8{'z'} ** 64;
    try testing.expectEqual(@as(usize, 3), main.mergeFeedWatchForTest(&ids, &hex, 1));

    // A redraw of the same feed is not news. Every tick rebuilds it, and
    // re-asking every relay four times a second is a different bug.
    const gen = main.feedWatchGenerationForTest();
    main.publishFeedWatchForTest(notes[0..]);
    try testing.expectEqual(gen, main.feedWatchGenerationForTest());

    // A feed that actually moved is.
    main.publishFeedWatchForTest(notes[0..2]);
    try testing.expect(main.feedWatchGenerationForTest() != gen);
}

