/// Whether the widget carrying this accessibility label has a handler behind it.
///
/// The dead-control guard walks the tree asking what each widget ADVERTISES, which
/// catches a `ui.button` or a `.checkbox` whose handler went missing. It cannot
/// catch a hand-built row losing its `on_press`: for a plain row the SDK derives
/// the advertised press FROM `on_press`, so removing it removes the advertisement
/// too and the widget stops being a button the guard is looking for. Naming the
/// control is the only way to assert it still exists AND still does something.
fn pressableByLabel(tree: AppUi.Tree, widget: canvas.Widget, label: []const u8) bool {
    if (std.mem.eql(u8, widget.semantics.label, label)) {
        for (tree.handlers) |h| {
            if (h.id == widget.id) return true;
        }
    }
    for (widget.children) |child| {
        if (pressableByLabel(tree, child, label)) return true;
    }
    return false;
}

/// The right-click items the first note in the tree offers, and the message
/// behind one of them by label.
///
/// The note's actions used to live in an anchored surface behind an ellipsis, so
/// tests reached them by opening that surface and looking for rendered text.
/// There is one list now and the runtime presents it, so what a test can see is
/// the declared items rather than drawn rows.
const ContextItems = struct {
    id: canvas.ObjectId,
    items: []const canvas.WidgetContextMenuItem,

    fn label(self: ContextItems, want: []const u8) ?canvas.WidgetContextMenuItem {
        for (self.items) |item| {
            if (std.mem.eql(u8, item.label, want)) return item;
        }
        return null;
    }

    fn msgFor(self: ContextItems, tree: AppUi.Tree, want: []const u8) ?Msg {
        for (self.items, 0..) |item, i| {
            if (std.mem.eql(u8, item.label, want)) return tree.msgForContextMenu(self.id, i);
        }
        return null;
    }
};

fn noteContext(p: painted.Painted) ?ContextItems {
    for (p.layout.nodes) |node| {
        if (node.widget.context_menu.len == 0) continue;
        return .{ .id = node.widget.id, .items = node.widget.context_menu };
    }
    return null;
}

/// The message behind the press on the widget carrying this accessibility label.
///
/// `pressableByLabel` asks whether SOMETHING is wired there. This asks what, which
/// is the difference between "the seat still works" and "the seat still goes where
/// it is supposed to".
fn pressMsgByLabel(tree: AppUi.Tree, label: []const u8) ?Msg {
    const w = findByLabel(tree.root, label) orelse return null;
    for (tree.handlers) |h| {
        if (h.id != w.id or h.event != .press) continue;
        return switch (h.action) {
            .message => |m| m,
            else => null,
        };
    }
    return null;
}

test "the rail's own seat opens your page, not your preferences" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    // A guest has no page to open, so the seat asks who they are. Unchanged.
    main.clearIdentityForTest();
    {
        var model = main.initialModel();
        model.stage = .ready;
        const tree = try buildTree(arena, &model);
        const msg = pressMsgByLabel(tree, "You") orelse return error.SeatHasNoPress;
        switch (msg) {
            .open_join => {},
            else => return error.GuestSeatGoesSomewhereElse,
        }
    }

    main.setIdentityForTest([_]u8{0x5A} ** 32);
    defer main.clearIdentityForTest();
    const me = main.activePubkeyForTest() orelse return error.NoIdentity;

    var model = main.initialModel();
    model.stage = .ready;
    const tree = try buildTree(arena, &model);
    const msg = pressMsgByLabel(tree, "You") orelse return error.SeatHasNoPress;
    switch (msg) {
        .open_person => |pk| try testing.expectEqualSlices(u8, &me, &pk),
        else => return error.SeatGoesSomewhereElse,
    }

    // The page it opens has to KNOW whose it is. Carrying the right thirty-two
    // bytes is not the same thing as landing on a screen that reads as yours,
    // and the screen is the part a reader sees.
    var fx: main.EffectsForTest = undefined;
    main.update(&model, msg, &fx);
    try testing.expectEqualSlices(u8, &me, &(model.viewing_profile orelse return error.NoProfile));
    const page = try buildTree(arena, &model);
    try testing.expect(findAnyText(page.root, "This is you") != null);
    // And offers no Follow. Following yourself writes your own contact list for
    // no reason, which is the one thing this app is most careful with.
    try testing.expect(findAnyText(page.root, "Follow") == null);
}

/// How many widgets in the tree carry exactly this text.
fn countAnyText(widget: canvas.Widget, text: []const u8) usize {
    var n: usize = if (std.mem.eql(u8, widget.text, text)) 1 else 0;
    for (widget.children) |child| n += countAnyText(child, text);
    return n;
}

test "a page with no name on it says the npub once" {
    main.resetProfilesForTest();
    defer main.resetProfilesForTest();
    main.setIdentityForTest([_]u8{0x6C} ** 32);
    defer main.clearIdentityForTest();

    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const who = [_]u8{0x2B} ** 32;
    var model = main.initialModel();
    model.stage = .ready;
    var fx: main.EffectsForTest = undefined;
    main.update(&model, .{ .open_person = who }, &fx);

    // The header band names whoever the page is about, which 11b asks for and
    // which is not the duplication at issue. So the band is the one legitimate
    // occurrence, and the question is whether the CARD says it again underneath
    // its own name line.
    const short = main.npubShortForTest(arena, who);
    try testing.expect(short.len > 0);

    // No kind:0, so `personName` hands back the short npub for the name line.
    // The npub row must then stand down: band + name line is two, and the row
    // would make three, the same string stacked on itself.
    const nameless = try buildTree(arena, &model);
    const said = countAnyText(nameless.root, short);
    if (said != 2) {
        std.debug.print("nameless page prints \"{s}\" {d} times, want 2 (band + name line)\n", .{ short, said });
        return error.SaidTwice;
    }

    // Given a name, the two lines carry different strings and both belong: the
    // band and the name line say "Grace", the row says the npub, once.
    const prof = main.upsertProfile(who).?;
    main.parseMetadataInto(prof, "{\"display_name\":\"Grace\"}");
    const named = try buildTree(arena, &model);
    try testing.expectEqual(@as(usize, 2), countAnyText(named.root, "Grace"));
    try testing.expectEqual(@as(usize, 1), countAnyText(named.root, short));
}

test "a suppressed npub does not shove the line beside it out of true" {
    // The npub row stands down for a nameless person. If it stands down by
    // becoming a zero-width spacer, the row's gap is still charged for it and
    // "follows you" lands 8px inside the left rule that the name, bio, links and
    // counts all share. `handleLine` documents that trap for the note row; this
    // is the profile card walking into it.
    main.resetProfilesForTest();
    defer main.resetProfilesForTest();
    main.setIdentityForTest([_]u8{0x4D} ** 32);
    defer main.clearIdentityForTest();
    const me = main.activePubkeyForTest() orelse return error.NoIdentity;

    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var pbuf: [128]u8 = undefined;
    const db_path = try std.fmt.bufPrintZ(&pbuf, ".zig-cache/tmp/{s}/follows.mdb", .{tmp.sub_path});
    var store = try nostr.store.Store.open(db_path, .{});
    defer store.deinit();
    main.setStoreForTest(&store);
    defer main.setStoreForTest(null);

    // Somebody with a contact list naming me and NO kind:0 at all. A real state,
    // not a contrived one: the two arrive as separate events, and a profile that
    // only ever set a picture never gets a name.
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    const kp = try signer.keyPairFromSecretKey([_]u8{0x51} ** 32);
    var me_hex: [64]u8 = undefined;
    _ = std.fmt.bufPrint(&me_hex, "{x}", .{&me}) catch unreachable;
    const tags = [_]nostr.event.Tag{&.{ "p", &me_hex }};
    const contacts = try nostr.event.create(arena, signer, kp, 1_800_000_000, 3, &tags, "", null);
    _ = try main.plazaIngestForTest(arena, contacts);

    var model = main.initialModel();
    model.stage = .ready;
    var fx: main.EffectsForTest = undefined;
    main.update(&model, .{ .open_person = kp.public_key }, &fx);

    const p = try painted.Painted.render(arena, &model);
    const follows = frameOfText(p, "follows you") orelse return error.NoFollowsLine;
    // The npub appears twice: the header band centres it, and the card's name
    // line carries it. The card's is the lower one, and it is the left rule that
    // matters here.
    const short = main.npubShortForTest(arena, kp.public_key);
    var name: ?native_sdk.geometry.RectF = null;
    for (p.layout.nodes) |node| {
        if (!std.mem.eql(u8, node.widget.text, short)) continue;
        if (name == null or node.widget.frame.y > name.?.y) name = node.widget.frame;
    }
    const name_line = name orelse return error.NoNameLine;
    // Same left rule, to within a hair of rounding.
    if (@abs(follows.x - name_line.x) > 1.0) {
        std.debug.print("\"follows you\" starts at x={d}, the name line at x={d}\n", .{ follows.x, name_line.x });
        return error.OutOfTrue;
    }
}

test "your own page is written for you, not about you" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    main.setIdentityForTest([_]u8{0x5A} ** 32);
    defer main.clearIdentityForTest();
    const me = main.activePubkeyForTest() orelse return error.NoIdentity;

    var model = main.initialModel();
    model.stage = .ready;
    var fx: main.EffectsForTest = undefined;

    // Your own page, freshly minted: no notes, no contact list read yet. This is
    // the exact state a reader who just pressed "Create your identity" arrives in,
    // and it is entirely made of the sentences that used to say "they".
    main.update(&model, .{ .open_person = me }, &fx);
    const mine = try buildTree(arena, &model);
    if (findAnyTextContainingText(mine.root, "they have written")) |s| {
        std.debug.print("own page talks about the reader in the third person: \"{s}\"\n", .{s});
        return error.WrongPerson;
    }
    try testing.expect(findAnyTextContainingText(mine.root, "you have written") != null);
    try testing.expect(findAnyText(mine.root, "Your follow list has not arrived yet") != null);

    // The line above is the LOADING one, and it is the only empty-tab string a
    // freshly opened profile can reach: `enterProfile` sets `thread_loading` from
    // an empty note count, and with no store it never clears. Settling it reaches
    // the other two, which otherwise sit behind an assertion that cannot see them
    // and could each be reverted to "they" with the suite still green.
    model.thread_loading = false;
    for ([_]struct { tab: @TypeOf(model.profile_tab), want: []const u8 }{
        .{ .tab = .notes, .want = "Nothing you have written is here yet." },
        .{ .tab = .replies, .want = "Nothing you have written at anyone is here yet." },
    }) |c| {
        model.profile_tab = c.tab;
        const settled = try buildTree(arena, &model);
        if (findAnyText(settled.root, c.want) == null) {
            std.debug.print("own page is missing \"{s}\"\n", .{c.want});
            return error.WrongPerson;
        }
        try testing.expect(findAnyTextContainingText(settled.root, "they have written") == null);
    }
    model.profile_tab = .notes;

    // A stranger's page is unchanged: it is about somebody else, and saying "you"
    // there would be the same mistake pointed the other way.
    main.update(&model, .{ .open_person = [_]u8{0x33} ** 32 }, &fx);
    const theirs = try buildTree(arena, &model);
    try testing.expect(findAnyTextContainingText(theirs.root, "they have written") != null);
    try testing.expect(findAnyText(theirs.root, "Their follow list has not arrived yet") != null);
    try testing.expect(findAnyTextContainingText(theirs.root, "you have written") == null);
}

/// Whether anything at or under `widget` is a focus stop.
fn holdsFocusStop(widget: canvas.Widget) bool {
    if (canvas.widgetIsFocusable(widget)) return true;
    for (widget.children) |child| {
        if (holdsFocusStop(child)) return true;
    }
    return false;
}

/// A sheet's backdrop, which closes the sheet when it is clicked. It is a
/// panel, dialog or card that does not call itself a button, and it holds the
/// sheet's own controls, which the keyboard does reach (and Escape closes it
/// besides). It is the pointer's shortcut and has no reason to be a stop of its
/// own. A row that merely CONTAINS focusable controls is not one: a note row
/// holds a like and a reply and still has to be reachable itself.
fn isBackdrop(widget: canvas.Widget) bool {
    switch (widget.kind) {
        .panel, .dialog, .card => {},
        else => return false,
    }
    if (widget.semantics.role != .none) return false;
    for (widget.children) |child| {
        if (holdsFocusStop(child)) return true;
    }
    return false;
}

/// Whether a focusable descendant of `widget` is bound to the very press it is.
/// A note row opens its thread when clicked, and so does the Reply verb inside
/// it; the row is the pointer's larger target for something the keyboard
/// already reaches, and a second stop beside it would read the note twice.
fn hasKeyboardTwin(tree: AppUi.Tree, widget: canvas.Widget, msg: Msg) bool {
    for (widget.children) |child| {
        if (canvas.widgetIsFocusable(child)) {
            if (tree.msgFor(child.id, .press)) |m| {
                if (std.meta.eql(m, msg)) return true;
            }
        }
        if (hasKeyboardTwin(tree, child, msg)) return true;
    }
    return false;
}

/// Walks one screen and fails on any press the keyboard cannot use. There are
/// three ways to be out of reach, and the first two shipped: a row bound to a
/// press with no focus stop (Tab walks past it); a row with a focus stop that is
/// a layout kind (the toolkit answers Return and Space, and draws a focus ring,
/// only for its own controls and `list_item`, so a `row` given `focusable` takes
/// focus, paints nothing and does nothing on either key); and a focus stop that
/// answers neither key.
fn expectKeyboardReach(tree: AppUi.Tree, widget: canvas.Widget, screen: []const u8) !void {
    if (tree.msgFor(widget.id, .press)) |msg| out: {
        if (widget.state.disabled or widget.semantics.hidden) break :out;
        // The card inside a sheet swallows presses so the backdrop does not
        // close it from under you. It is not a control.
        if (msg == .absorb_press) break :out;
        if (!canvas.widgetIsFocusable(widget)) {
            if (isBackdrop(widget) or hasKeyboardTwin(tree, widget, msg)) break :out;
            std.debug.print(
                "\n{s}: a {s} \"{s}\" answers a press and the keyboard cannot reach it (build it with pressRow)\n",
                .{ screen, @tagName(widget.kind), widget.semantics.label },
            );
            return error.PressNotReachableByKeyboard;
        }
        // An inline link is the toolkit's own text hit-area. It is a focus stop
        // that draws no ring (upstream), and `keyActivation` is what makes Return
        // open it. Everything else must be a kind the toolkit rings and answers.
        const inline_link = widget.kind == .text and widget.semantics.role == .link;
        for ([_][]const u8{ "enter", "space" }) |name| {
            const key = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = name, .focused_id = widget.id };
            const answered = if (inline_link)
                main.keyActivation(tree, key) != null
            else
                canvas.widgetKeyboardControlIntent(widget, key) != null;
            if (!answered) {
                std.debug.print(
                    "\n{s}: a {s} \"{s}\" takes focus and {s} does nothing on it, and it draws no focus ring (build it with pressRow)\n",
                    .{ screen, @tagName(widget.kind), widget.semantics.label, name },
                );
                return error.FocusedPressDoesNothing;
            }
        }
    }
    for (widget.children) |child| try expectKeyboardReach(tree, child, screen);
}

test "every press on every screen can be reached and fired from the keyboard" {
    // The overflow sweep above visits sixteen screens as a guest. This visits the
    // ones a signed-in reader sees as well, because most of them are built by
    // different code: the composer, the notifications page, the profile editor,
    // the sheets that only open for somebody with a key. A guard that only ever
    // looked at the guest feed would pass with half the app unreachable.
    const States = enum { feed, feed_no_reply_verb, thread, thread_nested, thread_no_reply_verb, own_profile, other_profile, bookmarks, settings, settings_editing, notifications, notifications_empty, composing, naming, address, joining, bunker, deleting, menu_scope, menu_relays, menu_account, relay_auth, relays_paused };

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var pbuf: [128]u8 = undefined;
    const db_path = try std.fmt.bufPrintZ(&pbuf, ".zig-cache/tmp/{s}/keys.mdb", .{tmp.sub_path});
    var store = try nostr.store.Store.open(db_path, .{});
    defer store.deinit();
    main.setStoreForTest(&store);
    defer main.setStoreForTest(null);

    const me = [_]u8{0x2f} ** 32;
    inline for (@typeInfo(States).@"enum".fields) |f| {
        const st: States = @enumFromInt(f.value);
        var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        // Signed in, except where the screen is the guest's.
        if (st == .joining or st == .bunker) main.clearIdentityForTest() else main.setIdentityForTest(me);
        defer main.clearIdentityForTest();
        // A reader can take the Reply verb away, and it is the keyboard's usual
        // way into a thread, so those screens are walked without it as well.
        main.setHidden(.replies, st == .feed_no_reply_verb or st == .thread_no_reply_verb);
        defer main.setHidden(.replies, false);
        defer main.resetInboxForTest();
        main.resetPlacesForTest();
        main.resetProfilesForTest();
        main.clearRelaysForTest();
        _ = main.addRelayForTest("wss://relay.example.org", true, true);
        main.seedInboxUnreadForTest(if (st == .notifications_empty) 0 else 3);
        // A relay that refused something until the reader identifies to it,
        // whose question sits above the feed with an Allow and a Don't allow.
        main.resetRelayAuthForTest();
        defer main.resetRelayAuthForTest();
        var auth_index: ?usize = null;
        if (st == .relay_auth) {
            auth_index = main.addRelayForTest(auth_test_url, true, true) orelse return error.NoSeat;
            var sess = main.AuthSessionForTest{ .index = auth_index.? };
            challengeAndRefuse(&sess, auth_test_url, "chal-keys", 0);
        }

        const model = try arena.create(main.Model);
        model.* = main.initialModel();
        model.stage = .ready;
        model.notes[0] = main.noteWithLinkForTest("https://example.com/a");
        model.notes_len = 1;
        switch (st) {
            .feed, .feed_no_reply_verb, .notifications_empty => {},
            .thread => {
                model.viewing_thread = model.notes[0].id;
                model.thread_root = model.notes[0];
                model.thread_notes[0] = model.notes[0];
                model.thread_notes_len = 1;
            },
            // A reply with a reply of its own, which draws as a nested row
            // with no verbs under it.
            .thread_nested, .thread_no_reply_verb => {
                model.viewing_thread = model.notes[0].id;
                model.thread_root = model.notes[0];
                model.thread_root.event_id = [_]u8{0xAA} ** 32;
                model.thread_notes[0] = threadNote(0xB1, 200, 0xAA);
                model.thread_notes[0].id = 61;
                model.thread_notes[1] = threadNote(0xC1, 300, 0xB1);
                model.thread_notes[1].id = 62;
                model.thread_notes_len = 2;
                main.arrangeThread(model.thread_notes[0..2], model.thread_root.event_id);
            },
            .own_profile => model.viewing_profile = me,
            .other_profile => model.viewing_profile = model.notes[0].pubkey,
            .bookmarks => model.viewing_bookmarks = true,
            .settings => model.stage = .settings,
            .settings_editing => {
                model.stage = .settings;
                model.editing_profile = true;
            },
            .notifications => model.notifications_open = true,
            .composing => model.composing = true,
            .naming => model.naming = true,
            .address => model.address_open = true,
            .joining => model.joining = true,
            .bunker => {
                model.joining = true;
                model.bunker_mode = true;
            },
            .deleting => model.deleting_note = model.notes[0].id,
            .menu_scope => model.menu = .scope,
            .menu_relays => model.menu = .relays,
            .menu_account => model.menu = .account,
            .relay_auth => {},
            // The quiet strip with a Resume in it, in place of the offline one.
            .relays_paused => model.relays_paused = true,
        }
        if (st == .notifications_empty) model.notifications_open = true;

        const tree = try buildTree(arena, model);
        // A screen the setup never reached has nothing to press and passes
        // the walk below, which reads exactly like coverage.
        if (countPresses(tree, tree.root) < 8) {
            std.debug.print("\nthe {s} screen drew {d} presses: it was never reached\n", .{ f.name, countPresses(tree, tree.root) });
            return error.ScreenNeverReached;
        }
        // And the nested reply is on it, or the thread screens walk only the
        // rows that were already reachable.
        if ((st == .thread_nested or st == .thread_no_reply_verb) and countPressesOf(tree, tree.root, Msg{ .open_thread = 62 }) == 0) {
            std.debug.print("\nthe {s} screen drew no nested reply\n", .{f.name});
            return error.ScreenNeverReached;
        }
        if (st == .relays_paused and countPressesOf(tree, tree.root, Msg.toggle_relays_paused) == 0) {
            std.debug.print("\nthe {s} screen drew no Resume\n", .{f.name});
            return error.ScreenNeverReached;
        }
        if (auth_index) |i| {
            if (countPressesOf(tree, tree.root, Msg{ .auth_allow = @intCast(i) }) == 0 or
                countPressesOf(tree, tree.root, Msg{ .auth_deny = @intCast(i) }) == 0)
            {
                std.debug.print("\nthe {s} screen drew no AUTH question\n", .{f.name});
                return error.ScreenNeverReached;
            }
        }
        expectKeyboardReach(tree, tree.root, f.name) catch |err| {
            std.debug.print("\nthe {s} screen has a press the keyboard cannot use\n", .{f.name});
            return err;
        };
    }
}

test "return and space press a focused inline link" {
    // The toolkit puts a Tab stop on every link inside a paragraph and answers
    // neither key on it, so a reader could tab onto a link in a note and nothing
    // would happen. `keyActivation` is what presses it.
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    main.clearIdentityForTest();

    var model = main.initialModel();
    model.stage = .ready;
    model.notes[0] = main.noteWithLinkForTest("");
    const body = "see https://example.com/a/page for the details";
    @memcpy(model.notes[0].content_buf[0..body.len], body);
    model.notes[0].content_len = @intCast(body.len);
    model.notes_len = 1;
    const tree = try buildTree(arena, &model);

    const link = findLinkWidget(tree.root) orelse return error.NoLinkInTheNote;
    const press = tree.msgFor(link.id, .press) orelse return error.LinkHasNoPress;
    for ([_][]const u8{ "enter", "space" }) |name| {
        const key = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = name, .focused_id = link.id };
        const got = main.keyActivation(tree, key) orelse return error.KeyDidNotPressTheLink;
        try testing.expect(std.meta.eql(got, press));
    }
    // Only the activation keys, only on key down, and not with a chord.
    const tab = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = "tab", .focused_id = link.id };
    try testing.expect(main.keyActivation(tree, tab) == null);
    const up = canvas.WidgetKeyboardEvent{ .phase = .key_up, .key = "enter", .focused_id = link.id };
    try testing.expect(main.keyActivation(tree, up) == null);
    const chord = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = "enter", .focused_id = link.id, .modifiers = .{ .super = true } };
    try testing.expect(main.keyActivation(tree, chord) == null);
    // And nothing at all when nothing has the keyboard.
    const nowhere = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = "enter" };
    try testing.expect(main.keyActivation(tree, nowhere) == null);
}

test "a notification's keyboard stop goes where it says" {
    // The age under a notification is the keyboard's way to what the row opens,
    // and it is labelled "Open note". A mention that answers nothing has no
    // target, so the row opens the person instead, and a stop there would be a
    // third way to the same profile under a label that says otherwise.
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    main.setIdentityForTest([_]u8{0xB9} ** 32);
    defer main.clearIdentityForTest();
    main.resetInboxForTest();
    defer main.resetInboxForTest();
    main.forgetFollowsForTest();

    var model = main.initialModel();
    model.stage = .ready;
    model.notifications_open = true;
    model.notifications_everyone = true;

    const me = main.activePubkeyForTest().?;
    var me_hex: [64]u8 = undefined;
    for (me, 0..) |b, i| _ = std.fmt.bufPrint(me_hex[i * 2 ..][0..2], "{x:0>2}", .{b}) catch {};
    const target = [_]u8{0x7E} ** 32;
    var target_hex: [64]u8 = undefined;
    for (target, 0..) |b, i| _ = std.fmt.bufPrint(target_hex[i * 2 ..][0..2], "{x:0>2}", .{b}) catch {};

    // A mention with no note under it: the row opens the person.
    const mention = [_]nostr.event.Tag{&.{ "p", &me_hex }};
    _ = main.inboxAddForTest(inboxEvent(1, 0xCA, &mention, 1_800_000_000), 1_800_000_000);
    {
        const tree = try buildTree(arena, &model);
        try testing.expect(findAnyTextContainingText(tree.root, "mentioned you in a note") != null);
        try testing.expectEqual(@as(usize, 0), countLabelled(tree.root, "Open note"));
    }

    // A reply to a note of the reader's: the stop is there and opens that note.
    const reply = [_]nostr.event.Tag{ &.{ "e", &target_hex, "", "reply" }, &.{ "p", &me_hex } };
    _ = main.inboxAddForTest(inboxEvent(1, 0xCB, &reply, 1_800_000_100), 1_800_000_100);
    {
        const tree = try buildTree(arena, &model);
        try testing.expectEqual(@as(usize, 1), countLabelled(tree.root, "Open note"));
        try testing.expect(countPressesOf(tree, tree.root, Msg{ .open_event = target }) > 0);
    }
}

fn countLabelled(widget: canvas.Widget, label: []const u8) usize {
    var n: usize = if (canvas.widgetIsFocusable(widget) and std.mem.eql(u8, widget.semantics.label, label)) 1 else 0;
    for (widget.children) |child| n += countLabelled(child, label);
    return n;
}

fn countPressesOf(tree: AppUi.Tree, widget: canvas.Widget, msg: Msg) usize {
    var n: usize = 0;
    if (tree.msgFor(widget.id, .press)) |m| {
        if (std.meta.eql(m, msg)) n += 1;
    }
    for (widget.children) |child| n += countPressesOf(tree, child, msg);
    return n;
}

fn countPresses(tree: AppUi.Tree, widget: canvas.Widget) usize {
    var n: usize = if (tree.msgFor(widget.id, .press) != null) 1 else 0;
    for (widget.children) |child| n += countPresses(tree, child);
    return n;
}

fn findLinkWidget(widget: canvas.Widget) ?canvas.Widget {
    if (widget.kind == .text and widget.semantics.role == .link) return widget;
    for (widget.children) |child| {
        if (findLinkWidget(child)) |found| return found;
    }
    return null;
}

test "every way into the app is wired, by name" {
    // Deleting `.on_press` from joinCard leaves three inert rectangles that still
    // say button, still focus, still paint, and still hold every string the other
    // tests assert on. The whole suite passed with the ladder dead.
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    main.clearIdentityForTest();

    {
        var model = main.initialModel();
        model.stage = .ready;
        model.joining = true;
        const tree = try buildTree(arena, &model);
        for ([_][]const u8{ "Create your identity", "Bring your key", "Use your own signer", "Keep browsing" }) |label| {
            if (!pressableByLabel(tree, tree.root, label)) {
                std.debug.print("join sheet: \"{s}\" is not pressable\n", .{label});
                return error.DeadControl;
            }
        }
    }

    {
        var model = main.initialModel();
        model.stage = .ready;
        model.naming = true;
        const tree = try buildTree(arena, &model);
        for ([_][]const u8{ "Done", "Skip" }) |label| {
            if (!pressableByLabel(tree, tree.root, label)) {
                std.debug.print("name card: \"{s}\" is not pressable\n", .{label});
                return error.DeadControl;
            }
        }
    }
}

test "a keyholder that is not there is reported missing, not formatted into a path" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var dir_buf: [std.fs.max_path_bytes]u8 = undefined;
    const dir_len = try tmp.dir.realPath(std.testing.io, &dir_buf);
    const dir = dir_buf[0..dir_len];

    var out: [1024]u8 = undefined;
    // Nothing beside us yet. Formatting a path is not finding a binary, and the
    // version of this that only formatted is what shipped a bundle with no
    // keyholder in it: the app spawned a file that was not there, said so on
    // stderr, and carried on believing it had a daemon.
    try testing.expectEqual(@as(usize, 0), main.resolveSiblingForTest(std.testing.io, &out, dir, "signer"));

    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "signer", .data = "not really a binary" });
    const n = main.resolveSiblingForTest(std.testing.io, &out, dir, "signer");
    var want_buf: [std.fs.max_path_bytes + 32]u8 = undefined;
    try testing.expectEqualStrings(
        try std.fmt.bufPrint(&want_buf, "{s}/signer", .{dir}),
        out[0..n],
    );
}

test "with no keyholder the create rung says why and stops being a button" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    main.clearIdentityForTest();
    main.setKeyholderMissingForTest(true);
    defer main.setKeyholderMissingForTest(false);

    var model = main.initialModel();
    model.stage = .ready;
    model.joining = true;
    const tree = try buildTree(arena, &model);

    // Still named, so the reader is not left hunting for where creating an
    // identity went. Just not a button, and not a promise: "every way into the
    // app is wired, by name" asserts the opposite of this on the same label, and
    // between them they pin both states.
    try testing.expect(findAnyText(tree.root, "Create your identity") != null);
    try testing.expectEqual(@as(?Msg, null), pressMsgByLabel(tree, "Create your identity"));
    try testing.expect(findAnyText(tree.root, "Not possible in this copy of Plaza.") != null);
    try testing.expect(findAnyText(tree.root, "Ready in seconds. Nothing to write down.") == null);
    // And the reason sits under the card, where a wrapping line has room to be
    // three lines long. `the ladder's rungs hold their own copy` is what keeps
    // it from drifting back INTO the card, where it paints outside the border.
    try testing.expect(findAnyTextContaining(tree.root, "is missing from this install"));

    // Bringing a key goes the same way, and for the same reason: there is
    // nowhere for a key to go. It used to fall back to a field in this process,
    // and that fallback is gone with the field. A rung that leads to a screen
    // refusing every key it is given is worse than one that says it cannot.
    try testing.expect(findAnyText(tree.root, "Bring your key") != null);
    try testing.expectEqual(@as(?Msg, null), pressMsgByLabel(tree, "Bring your key"));

    // The rung that still works is the one that needs nothing from this
    // machine: your key is already in a signer somewhere else.
    try testing.expect(pressableByLabel(tree, tree.root, "Use your own signer"));
    try testing.expect(findAnyText(tree.root, "Opens Notary. Plaza itself never sees it.") == null);
    // And nothing anywhere still offers to keep a key in this app, which is a
    // promise it can no longer make about anything.
    try testing.expect(findAnyText(tree.root, "Pasted here, and kept on this device.") == null);
}

