// ---- NIP-22: a reply of either kind reaches me ------------------------------

test "a comment's parent and root are read from its own vocabulary" {
    // NIP-22 has no marker vocabulary at all, and field 4 of its `e` is the
    // AUTHOR pubkey where NIP-10 puts a marker. Reading one as the other is how
    // a reader quietly starts mistaking every comment for an unmarked
    // positional reply, so the two readers stay separate and a dispatcher picks.
    const root_id = [_]u8{0xE1} ** 32;
    const parent_id = [_]u8{0xE2} ** 32;
    var root_hex: [64]u8 = undefined;
    var parent_hex: [64]u8 = undefined;
    _ = std.fmt.bufPrint(&root_hex, "{x}", .{root_id}) catch unreachable;
    _ = std.fmt.bufPrint(&parent_hex, "{x}", .{parent_id}) catch unreachable;

    // The ordinary shape: uppercase names the root, lowercase the note being
    // answered, and the fourth field is a pubkey rather than a marker.
    const nested = [_]nostr.event.Tag{
        &.{ "E", &root_hex, "wss://relay.example", "f" ** 64 },
        &.{ "K", "1" },
        &.{ "e", &parent_hex, "wss://relay.example", "a" ** 64 },
        &.{ "k", "1111" },
    };
    try testing.expectEqualSlices(u8, &parent_id, &(main.nip22Parent(&nested).?));
    try testing.expectEqualSlices(u8, &root_id, &(main.nip22Root(&nested).?));

    // A top-level comment answers the root directly and carries no lowercase
    // `e` at all, so the parent falls back to the uppercase.
    const top = [_]nostr.event.Tag{
        &.{ "E", &root_hex, "", "f" ** 64 },
        &.{ "K", "30023" },
    };
    try testing.expectEqualSlices(u8, &root_id, &(main.nip22Parent(&top).?));

    // A comment on a URL or a hashtag has no event parent at all. Calling one
    // of those a reply to something would be inventing a tie.
    const on_a_url = [_]nostr.event.Tag{
        &.{ "I", "https://example.com/a" },
        &.{ "K", "web" },
    };
    try testing.expect(main.nip22Parent(&on_a_url) == null);
    try testing.expect(main.nip22Root(&on_a_url) == null);

    // And the dispatcher keeps the two vocabularies apart. These same tags read
    // as NIP-10 would answer with the LAST plain `e`, which is the parent here
    // by luck; the root is what separates them, because NIP-10 has no `E`.
    try testing.expectEqualSlices(u8, &parent_id, &(main.replyParent(main.comment_kind, &nested).?));
    try testing.expectEqualSlices(u8, &root_id, &(main.replyRoot(main.comment_kind, &nested).?));

    // And this is why the dispatcher exists rather than one reader with a
    // branch inside it. Handed the SAME tags, the NIP-10 reader finds no `root`
    // marker (field 4 is a pubkey), takes the first unmarked `e`, and answers
    // that the root is the PARENT. Not null, not an error: a confident wrong
    // answer, which is the shape of bug that survives review.
    try testing.expectEqualSlices(u8, &parent_id, &(main.replyRoot(1, &nested).?));
}

test "a comment naming me is a notification, by either p tag" {
    const me = [_]u8{0x11} ** 32;
    var me_hex: [64]u8 = undefined;
    _ = std.fmt.bufPrint(&me_hex, "{x}", .{me}) catch unreachable;
    const other_hex = "cc" ** 32;
    const root_hex = "ee" ** 32;

    // The kind has to be in BOTH gates. In `inbox_kinds` so a relay is asked,
    // and in the verb switch so a row exists; a kind in one but not the other
    // is a subscription paying for events nobody draws.
    var found = false;
    for (main.inbox_kinds) |k| {
        if (k == main.comment_kind) found = true;
    }
    try testing.expect(found);

    // Answering MY note: the lowercase `p` is the author of what is answered.
    const answers_me = [_]nostr.event.Tag{
        &.{ "E", root_hex, "", other_hex },
        &.{ "e", root_hex, "", other_hex },
        &.{ "p", &me_hex },
    };
    try testing.expectEqual(main.InboxVerb.reply, main.inboxVerbForTest(main.commentEventForTest(0xC1, &answers_me), me).?);

    // Named ONLY in the uppercase `P`: I started the thread, but this comment
    // answers somebody else's comment in it. NOT a notification, which is what
    // the reference clients do. Amethyst's notification subscription asks for
    // lowercase `p` and its classifier is `it[0] == "p"`; Jumble's filter is
    // `'#p': [pubkey]`. Both carry kind 1111, so the narrowing is deliberate.
    //
    // Amethyst parses `P` as `RootAuthorTag` and spends it on `pubKeyHints()`
    // and `linkedPubKeys()`, which is relay hints and profile prefetching, not
    // the inbox. It is easy to read that as "Amethyst admits both" and be
    // wrong.
    //
    // The behaviour: a thread I started can run for a hundred messages between
    // other people, and telling me about each one is the hellthread problem in
    // NIP-22 clothing.
    const on_my_root = [_]nostr.event.Tag{
        &.{ "E", root_hex, "", &me_hex },
        &.{ "P", &me_hex },
        &.{ "e", root_hex, "", other_hex },
        &.{ "p", other_hex },
    };
    try testing.expect(main.inboxVerbForTest(main.commentEventForTest(0xC2, &on_my_root), me) == null);

    // A comment naming somebody else entirely is still not mine.
    const names_other = [_]nostr.event.Tag{
        &.{ "E", root_hex, "", other_hex },
        &.{ "e", root_hex, "", other_hex },
        &.{ "p", other_hex },
    };
    try testing.expect(main.inboxVerbForTest(main.commentEventForTest(0xC3, &names_other), me) == null);
}

test "hiding replies stops asking relays for comments too" {
    // A comment IS a reply, so it follows the reply preference. Leaving it in
    // while replies are hidden would ask relays for the thing the reader turned
    // off, which is the exact overclaim `engagementKinds` exists to prevent.
    for (0..main.hideables.len) |i| main.setHidden(@enumFromInt(i), false);
    defer for (0..main.hideables.len) |i| main.setHidden(@enumFromInt(i), false);

    try testing.expectEqualSlices(u16, &.{ 1, 1111, 6, 7, 9735 }, main.engagementKindsForTest());

    main.setHidden(.replies, true);
    for (main.engagementKindsForTest()) |k| {
        try testing.expect(k != main.comment_kind);
        try testing.expect(k != 1);
    }
}

// ---- NIP-36 content warnings --------------------------------------------------

fn warnedEvent(id_byte: u8, content: []const u8, tags: []const nostr.event.Tag) nostr.event.Event {
    return .{
        .id = [_]u8{id_byte} ** 32,
        .pubkey = [_]u8{0x61} ** 32,
        .created_at = 1_800_000_000,
        .kind = 1,
        .tags = tags,
        .content = content,
        .sig = [_]u8{0} ** 64,
    };
}

test "the content-warning tag is read with a reason, without one, and when malformed" {
    // The TAG is the warning, not the sentence in it. A bare tag, an empty reason
    // and a reason with a control character in it all ask for the note to be
    // covered, and only the first of those has no words to show.
    const none = [_]nostr.event.Tag{&.{ "t", "nostr" }};
    try testing.expect(main.contentWarningIn(&none) == null);

    const with_reason = [_]nostr.event.Tag{&.{ "content-warning", "  spoilers  " }};
    try testing.expectEqualStrings("spoilers", main.contentWarningIn(&with_reason).?);

    const bare = [_]nostr.event.Tag{&.{"content-warning"}};
    try testing.expectEqualStrings("", main.contentWarningIn(&bare).?);

    const empty = [_]nostr.event.Tag{&.{ "content-warning", "" }};
    try testing.expectEqualStrings("", main.contentWarningIn(&empty).?);

    const control = [_]nostr.event.Tag{&.{ "content-warning", "bad\x00reason" }};
    try testing.expectEqualStrings("", main.contentWarningIn(&control).?);

    // Clipped on a character boundary: 60 three-byte characters cannot be cut
    // through the middle of one.
    const long = [_]nostr.event.Tag{&.{ "content-warning", "日本語" ** 20 }};
    const clipped = main.contentWarningIn(&long).?;
    try testing.expect(clipped.len < ("日本語" ** 20).len);
    try testing.expect(std.unicode.utf8ValidateSlice(clipped));
}

test "a note carries its author's content warning and the reason they gave" {
    const tags = [_]nostr.event.Tag{&.{ "content-warning", "spoilers" }};
    const warned = main.noteFrom(warnedEvent(0xC0, "the butler did it", &tags), 1_800_000_100);
    try testing.expect(warned.warned);
    try testing.expectEqualStrings("spoilers", warned.warning());

    const plain = main.noteFrom(warnedEvent(0xC1, "good morning", &.{}), 1_800_000_100);
    try testing.expect(!plain.warned);
    try testing.expectEqual(@as(usize, 0), plain.warning().len);
}

test "a covered note shows who wrote it and why, and nothing it says or points at" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    main.forgetUncoveredForTest();
    defer main.forgetUncoveredForTest();
    main.setShowSensitive(false);
    // Previews off so a press that uncovers a picture asks for nothing: a test
    // cannot construct a usable effect table.
    const previews_were = main.mediaPreviews();
    main.setMediaPreviews(false);
    defer main.setMediaPreviews(previews_were);

    var model = main.initialModel();
    model.stage = .ready;
    const first_tags = [_]nostr.event.Tag{&.{ "content-warning", "spoilers" }};
    const second_tags = [_]nostr.event.Tag{&.{"content-warning"}};
    model.notes[0] = main.noteFrom(warnedEvent(0xC2, "FIRSTSECRET https://example.com/a.jpg", &first_tags), 1_800_000_100);
    model.notes[1] = main.noteFrom(warnedEvent(0xC3, "SECONDSECRET", &second_tags), 1_800_000_100);
    model.notes[2] = main.noteFrom(warnedEvent(0xC4, "PLAINWORDS", &.{}), 1_800_000_100);
    model.notes_len = 3;

    const before = try buildTree(arena, &model);
    // The words are not in the tree at all, so they cannot be read, copied from
    // the accessibility tree or drawn by a later change that forgets to check.
    try testing.expect(!findAnyTextContaining(before.root, "FIRSTSECRET"));
    try testing.expect(!findAnyTextContaining(before.root, "SECONDSECRET"));
    try testing.expect(findAnyTextContaining(before.root, "PLAINWORDS"));
    // The reason, when there is one, and the plain notice when there is not.
    try testing.expect(findAnyTextContaining(before.root, "Content warning: spoilers"));
    try testing.expect(findAnyText(before.root, "Content warning") != null);
    try testing.expectEqual(@as(usize, 2), countByLabel(before.root, "Show this note"));
    // And no picture: not drawn, and not offered as one to load either.
    try testing.expectEqual(@as(usize, 0), countByLabel(before.root, "Attached image, press to enlarge"));
    try testing.expectEqual(@as(usize, 0), countByLabel(before.root, "Load this image"));

    // Pressing uncovers THAT note and no other.
    const msg = pressMsgByLabel(before, "Show this note") orelse return error.NothingToPress;
    switch (msg) {
        .uncover_note => |key| try testing.expectEqual(model.notes[0].id, key),
        else => return error.WrongPress,
    }
    var fx: main.EffectsForTest = undefined;
    main.update(&model, msg, &fx);

    const after = try buildTree(arena, &model);
    try testing.expect(findAnyTextContaining(after.root, "FIRSTSECRET"));
    try testing.expect(!findAnyTextContaining(after.root, "SECONDSECRET"));
    try testing.expectEqual(@as(usize, 1), countByLabel(after.root, "Show this note"));
    // The picture is now offered, which means it was not before.
    try testing.expectEqual(@as(usize, 1), countByLabel(after.root, "Load this image"));
}

test "the setting for readers who would rather see everything is off, and does what it says" {
