}

test "a bunker pairing that is taken back leaves its secret nowhere" {
    defer main.resetBunkerConnectForTest();
    defer main.clearIdentityForTest();
    main.setIoForTest(testing.io);
    defer main.setIoForTest(null);
    var model = main.initialModel();
    model.stage = .ready;
    model.joining = true;
    model.bunker_mode = true;
    var fx: main.EffectsForTest = undefined;
    const link = "bunker://" ++ "ab" ** 32 ++ "?relay=wss://127.0.0.1:1&secret=pairing-secret-one";

    // The signer refuses, or the relay never carried the request.
    model.login_buffer.set(link);
    main.update(&model, .login_submit, &fx);
    try testing.expect(main.bunkerConnecting());
    try testing.expect(main.remoteSecretHeldForTest("pairing-secret-one"));
    var id_buf: [24]u8 = undefined;
    const id = main.pendingConnectIdForTest(&id_buf) orelse return error.NoConnectRequest;
    try testing.expect(main.failPendingForTest(id));
    main.scanPendingRemoteForTest(&model, &fx);
    main.driveBunkerConnectForTest(&model);
    try testing.expect(!main.bunkerConnecting());
    // A length of zero is not the same as gone: the bytes are wiped, and the
    // client key with them.
    try testing.expect(!main.remoteSecretHeldForTest("pairing-secret-one"));

    // And the same when the reader backs out while it waits.
    model.login_buffer.set(link);
    main.update(&model, .login_submit, &fx);
    try testing.expect(main.remoteSecretHeldForTest("pairing-secret-one"));
    main.update(&model, .close_bunker, &fx);
    try testing.expect(!main.bunkerConnecting());
    try testing.expect(!main.remoteSecretHeldForTest("pairing-secret-one"));
}

test "a key adopted while a bunker link waits takes the link down with it" {
    defer main.resetBunkerConnectForTest();
    defer main.clearIdentityForTest();
    main.setIoForTest(testing.io);
    defer main.setIoForTest(null);
    var model = main.initialModel();
    model.stage = .ready;
    model.joining = true;
    model.bunker_mode = true;
    var fx: main.EffectsForTest = undefined;

    model.login_buffer.set("bunker://" ++ "ab" ** 32 ++ "?relay=wss://127.0.0.1:1&secret=pairing-secret-two");
    main.update(&model, .login_submit, &fx);
    try testing.expect(main.bunkerConnecting());
    const generation = main.remoteGenerationForTest();

    // An import finished in Notary meanwhile, and the keyholder's key was
    // adopted. That account is the reader's now.
    main.setIdentityForTest([_]u8{0x6A} ** 32);
    main.driveBunkerConnectForTest(&model);

    try testing.expect(!main.bunkerConnecting());
    try testing.expect(!model.is_guest());
    try testing.expectEqualStrings("helper", main.signerKindNameForTest());
    // The pairing went with it: its listener was told to stop, nothing waits
    // on its answer, and its secret is gone.
    try testing.expect(main.remoteGenerationForTest() != generation);
    var id_buf: [24]u8 = undefined;
    try testing.expect(main.pendingConnectIdForTest(&id_buf) == null);
    try testing.expect(!main.remoteSecretHeldForTest("pairing-secret-two"));
}

test "a connect answered by the signer is never read as one that never went out" {
    defer main.resetBunkerConnectForTest();
    defer main.clearIdentityForTest();
    // The listener takes an answer on its own thread while the tick asks
    // whether the request is still out. Between "the slot is gone" and "the
    // connection is up" there must be no moment the tick can see, or a signer
    // that said yes is reported as silent and the reader is turned away.
    const Listener = struct {
        go: std.atomic.Value(u32) = .init(0),
        done: std.atomic.Value(u32) = .init(0),
        id: []const u8 = "",
        fn run(self: *@This(), rounds: u32) void {
            var round: u32 = 1;
            while (round <= rounds) : (round += 1) {
                while (self.go.load(.acquire) != round) std.atomic.spinLoopHint();
                main.answerBunkerConnectForTest(self.id);
                self.done.store(round, .release);
            }
        }
    };
    const rounds: u32 = 20_000;
    var listener: Listener = .{};
    var id_buf: [24]u8 = undefined;
    const thread = try std.Thread.spawn(.{}, Listener.run, .{ &listener, rounds });
    var misread: u32 = 0;
    var round: u32 = 1;
    while (round <= rounds) : (round += 1) {
        listener.id = main.beginBunkerConnectForTest([_]u8{0x5E} ** 32, &id_buf);
        listener.go.store(round, .release);
        while (listener.done.load(.acquire) != round) {
            if (main.connectWentQuietForTest()) misread += 1;
        }
    }
    thread.join();
    try testing.expectEqual(@as(u32, 0), misread);
}

test "a half written reply survives a trip to a hashtag page or an article, and an article's newer copy" {
    // The reply box is parked under its thread whenever the level changes. The
    // hashtag page and the article reader are levels too, and an article swaps
    // its root in place when a newer copy lands, which is not a level change:
    // the reply being typed under it must stay where it is.
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    const kp = try signer.keyPairFromSecretKey([_]u8{0x6e} ** 32);

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var pbuf: [160]u8 = undefined;
    var store = try articleStore(&tmp, &pbuf, "parked");
    defer store.deinit();
    main.setStoreForTest(&store);
    defer main.setStoreForTest(null);
    main.forgetArticleForTest();
    defer main.forgetArticleForTest();
    main.forgetAddressFetchForTest();
    defer main.forgetAddressFetchForTest();

    const note = try signedNote(arena, signer, kp, 1_800_000_000, "a note with a #zig tag");
    _ = try main.plazaIngestVerifiedForTest(arena, note, signer);
    const tags = [_]nostr.event.Tag{&[_][]const u8{ "d", "kept-reply" }};
    const first = try signedKind(arena, signer, kp, 1_800_000_000, 30023, &tags, "The first copy.");
    const second = try signedKind(arena, signer, kp, 1_800_005_000, 30023, &tags, "The copy that was edited since.");
    _ = try main.plazaIngestVerifiedForTest(arena, first, signer);

    var model = main.initialModel();
    model.stage = .ready;
    main.enterThreadForTest(&model, main.noteFrom(note, 1_800_000_100));
    model.reply_buffer.set("half a thought");

    // Out to the hashtag page and Back.
    main.openTopicForTest(&model, "zig");
    try testing.expectEqualStrings("", model.reply_draft());
    main.closeThreadForTest(&model);
    try testing.expectEqualStrings("half a thought", model.reply_draft());

    // Out to an article and Back.
    main.openEventForTest(&model, first.id);
    try testing.expect(std.mem.eql(u8, &model.thread_root.event_id, &first.id));
    try testing.expectEqualStrings("", model.reply_draft());
    main.closeThreadForTest(&model);
    try testing.expectEqualStrings("half a thought", model.reply_draft());

    // A reply typed under the article stays put when a newer copy swaps in.
    main.closeThreadForTest(&model);
    main.openAddressedArticleForTest(&model, 30023, kp.public_key, "kept-reply");
    try testing.expect(std.mem.eql(u8, &model.thread_root.event_id, &first.id));
    model.reply_buffer.set("about the article");
    _ = try main.plazaIngestVerifiedForTest(arena, second, signer);
    _ = try buildTree(arena, &model);
    main.refreshAddressFetchForTest(&model);
    try testing.expect(std.mem.eql(u8, &model.thread_root.event_id, &second.id));
    try testing.expectEqualStrings("about the article", model.reply_draft());
}

test "a person found by name or by NIP-05 over Settings leaves Settings" {
    // The search field is the address field, and Cmd+L opens it over Settings.
    // A pressed result or a domain's answer opens a person's page, which is
    // drawn under Settings, so it has to leave Settings the way an address does.
    main.searchResetForTest();
    defer main.searchResetForTest();
    var fx: main.EffectsForTest = undefined;

    {
        var model = main.initialModel();
        model.stage = .ready;
        main.update(&model, Msg.open_settings, &fx);
        main.update(&model, Msg.open_address, &fx);
        try testing.expectEqual(main.Stage.settings, model.stage);
        const pk = [_]u8{0x4e} ** 32;
        main.update(&model, Msg{ .search_pick = pk }, &fx);
        try testing.expectEqual(main.Stage.ready, model.stage);
        try testing.expectEqualSlices(u8, &pk, &(model.viewing_profile orelse return error.NoProfile));
    }
    {
        const hex = "4f" ** 32;
        var model = main.initialModel();
        model.stage = .ready;
        main.update(&model, Msg.open_settings, &fx);
        typeIntoSearch(&model, "alice@example.com");
        main.update(&model, Msg.address_submit, &fx);
        try testing.expectEqual(main.Stage.settings, model.stage);
        main.handleNip05FoundForTest(&model, .{ .key = main.nip05AskKeyForTest(), .status = 200, .body = "{\"names\":{\"alice\":\"" ++ hex ++ "\"}}" });
        try testing.expectEqual(main.Stage.ready, model.stage);
        try testing.expectEqualSlices(u8, &([_]u8{0x4f} ** 32), &(model.viewing_profile orelse return error.NoProfile));
    }
}

test "a re-issued feed that a relay refuses for want of AUTH is asked again once the relay says yes" {
    // The feed is closed and asked again under a new id each time its question
    // changes (`plaza-feed-<generation>`), and sign-in is one of those times, so
    // the feed a relay refuses for want of AUTH is almost never the bare
    // `plaza-feed` any more. Matched by name alone, the refusal was not recorded
    // as owed, nothing was re-sent after the relay accepted the reply, and that
    // relay sent the reader no feed for the rest of the connection.
    const idx = try authFixture();
    defer authCleanup();
    const me = main.activePubkeyForTest().?;
    var rec = AuthRecorder{};
    var fx: main.EffectsForTest = undefined;

    try testing.expect(main.setAuthChoiceForTest(me, auth_test_url, .allow));
    main.authSlotResetForTest(idx);
    var sess = main.AuthSessionForTest{ .index = idx };
    _ = main.authReactForTest(&sess, auth_test_url, authMsg("after-sign-in"), 0);
    const refused = main.authReactForTest(&sess, auth_test_url, closedMsg("plaza-feed-7", "auth-required: log in"), 1);
    try testing.expect(refused.handled);
    try testing.expectEqualStrings("want_sign", main.authPhaseNameForTest(idx));
    main.driveRelayAuthForTest(&fx);
    _ = main.authPollForTest(&sess, auth_test_url, &rec, 2);
    try testing.expectEqual(@as(usize, 1), rec.sent);
    const ok = main.authReactForTest(&sess, auth_test_url, .{ .ok = .{ .event_id = rec.id, .accepted = true, .message = "" } }, 3);
    try testing.expect(ok.resend.feed);
    try testing.expect(!ok.resend.inbox);
    try testing.expect(!ok.resend.engagement);
}

test "every toast the app can show fits the toast whole" {
    // The toast is one line of text over a 48-byte buffer, and `setToast` cuts
    // at the buffer, so a longer sentence reaches the reader as the first half of
    // one: "Could not read your follow list from your relays", and the rest of
    // what it meant gone. The limit is the buffer and not the width: 48 bytes of
    // the toast's text size is far narrower than the window at its minimum.
    const cap = main.initialModel().toast_buf.len;

    // Every string literal handed to `setToast`, read out of the source, so a new
    // toast is checked the day it is written rather than when somebody notices.
    // Every file of the app, joined, so a toast is found wherever its call sits.
    var joined: std.ArrayList(u8) = .empty;
    defer joined.deinit(testing.allocator);
    for (app_sources) |s| {
        try joined.append(testing.allocator, '\n');
        try joined.appendSlice(testing.allocator, s.text);
    }
    const source = joined.items;
    var calls: usize = 0;
    var too_long: usize = 0;
    var at: usize = 0;
    while (std.mem.indexOfPos(u8, source, at, "setToast(")) |start| {
        at = start + "setToast(".len;
        // The call's own text, to its closing parenthesis, skipping string
        // contents so a ")" inside a sentence does not end it early.
        var depth: usize = 1;
        var i = at;
        var in_string = false;
        while (i < source.len and depth > 0) : (i += 1) {
            const c = source[i];
            if (in_string) {
                if (c == '\\') {
                    i += 1;
                } else if (c == '"') in_string = false;
            } else if (c == '"') {
                in_string = true;
            } else if (c == '(') {
                depth += 1;
            } else if (c == ')') depth -= 1;
        }
        const call = source[at..i];
        if (std.mem.startsWith(u8, call, "model: *Model")) continue; // the definition
        calls += 1;
        var j: usize = 0;
        while (std.mem.indexOfScalarPos(u8, call, j, '"')) |open| {
            const close = std.mem.indexOfScalarPos(u8, call, open + 1, '"') orelse break;
            const text = call[open + 1 .. close];
            j = close + 1;
            // An argument to a helper (`noListToast("bookmarks")`) is not itself
            // shown; the helper's sentences are checked below.
            if (std.mem.indexOf(u8, call[0..open], "noListToast(") != null) continue;
            if (text.len > cap) {
                std.debug.print("\ntoo long for the toast ({d} bytes): {s}\n", .{ text.len, text });
                too_long += 1;
            }
        }
    }
    // The walk found the calls, and is not passing because it read nothing.
    try testing.expect(calls > 50);

    for (main.noListToastsForTest()) |text| {
        if (text.len > cap) {
            std.debug.print("\ntoo long for the toast ({d} bytes): {s}\n", .{ text.len, text });
            too_long += 1;
        }
    }
    try testing.expect(main.place_looking_toast_for_test.len <= cap);
    try testing.expectEqual(@as(usize, 0), too_long);
}

